YH_EXAM_BANKS["MKT231-CH"] = {"id":"MKT231-CH","course":"MKT 231","short":"فصول المقرر","lang":"ar","version":1,"los":[{"lo":"CH1","ar":"طبيعة سلوك المستهلك وأهميته","en":""},{"lo":"CH2","ar":"اتخاذ القرار الشرائي","en":""},{"lo":"CH4","ar":"تصميم الموقع التنافسي للمنتج","en":""},{"lo":"CH5","ar":"تأثير ثقافة المجتمع على سلوك المستهلك","en":""},{"lo":"CH6","ar":"الطبقات الاجتماعية وتأثيرها على السلوك الاستهلاكي للأفراد","en":""}],"sections":{"MKT231-CH1":{"ar":"الفصل الأول — طبيعة سلوك المستهلك وأهميته"},"MKT231-CH2":{"ar":"الفصل الثاني — اتخاذ القرار الشرائي"},"MKT231-CH4":{"ar":"الفصل الرابع — تصميم الموقع التنافسي للمنتج"},"MKT231-CH5":{"ar":"الفصل الخامس — تأثير ثقافة المجتمع على سلوك المستهلك"},"MKT231-CH6":{"ar":"الفصل السادس — الطبقات الاجتماعية وتأثيرها على السلوك الاستهلاكي للأفراد"}},"misconceptions":[{"id":"k1.family-is-org","ar":"يحسب شراء الأسرة مستهلك تنظيمي","explain":"يشوف كلمة «أسرة» أو «مجموعة» ويحسبها منظمة. بس الشريحة حاطة الاستهلاك العائلي (مثل شراء المواد الغذائية للأسرة) داخل تعريف المستهلك الفردي أو النهائي، والتنظيمي للمنشآت والمؤسسات والهيئات بس.","fix":"شريحة 6 — اقرأ تعريف المستهلك الفردي وركز على الغرضين: استعمال شخصي واستهلاك عائلي.","coach":"اعطه ٥ مواقف سريعة (أب يحجز شاليه للعايلة، فندق يشتري مفارش، جمعية خيرية تستأجر باص، شاب يشتري تذكرة لنفسه، وزارة تحجز قاعة مؤتمر) وخله يقول فردي ولا تنظيمي ويبرر بكلمة من التعريف.","sec":"MKT231-CH1"},{"id":"k1.org-means-profit","ar":"يحسب المستهلك التنظيمي شركات ربحية بس","explain":"ينسى الجهات اللي ما تبغى ربح. التعريف يشمل المنشآت التجارية والصناعية والزراعية والمؤسسات الحكومية والهيئات غير التجارية اللي ما تستهدف الربح كالجمعيات الخيرية.","fix":"شريحة 6 — عدّ الأنواع الخمسة في تعريف المستهلك التنظيمي.","coach":"اطلب منه يعد الخمسة أنواع بدون ما يشوف الورقة؛ إذا نسى الحكومية أو الجمعيات الخيرية يعيدها مرتين.","sec":"MKT231-CH1"},{"id":"k1.physical-vs-mental","ar":"يحسب جمع المعلومات نشاط ذهني","explain":"كلمة «معلومات» تخليه يحسبها تفكير. الشريحة تحط التسوق والتحدث مع رجال البيع وجمع المعلومات اللازمة تحت الأنشطة البدنية، وتحليل المعلومات والمقارنة واتخاذ القرار تحت الذهنية.","fix":"شريحة 7 — الافتراض الثاني (نوعين من الأنشطة).","coach":"قل له ٦ أفعال مخلوطة (يجمع، يحلل، يتسوق، يقارن، يكلم البائع، يقرر) وخله يفرزها بدني/ذهني بأسرع ما يقدر.","sec":"MKT231-CH1"},{"id":"k1.behavior-random","ar":"يحسب سلوك المستهلك عشوائي بلا هدف","explain":"الشريحة تقول السلوك مو اعتباطي ولا عشوائي «في أغلب الأحوال»، ويوجهه هدف أو مجموعة أهداف لإشباع حاجات غير مشبعة حالياً. وبعض الطلاب يروح للطرف الثاني ويقول «دائماً» مع الشريحة قالت «في أغلب الأحوال».","fix":"شريحة 7 — الافتراض الثالث.","coach":"اسأله: وش الكلمات اللي تخلي العبارة مو مطلقة؟ (في أغلب الأحوال) — وخله يكمل الجملة من حفظه لين «حاجاته غير المشبعة حالياً».","sec":"MKT231-CH1"},{"id":"k1.individual-vs-group","ar":"يحسب قرار إجازة الأسرة قرار فردي","explain":"يربط القرار بالشخص اللي يدفع (الأب). الشريحة تعطي «قرار الأسرة بقضاء الأجازة الصيفية بالخارج» مثال للقرار الجماعي، وشراء كتاب مثال للفردي.","fix":"شريحة 7 — الافتراض الأول.","coach":"اعطه مواقف سياحية (شاب يحجز تذكرة لنفسه، عائلة تختار وجهة الصيف، شلة تحجز استراحة) وخله يصنف فردي/جماعي.","sec":"MKT231-CH1"},{"id":"k1.five-questions-mixup","ar":"يلخبط بين كيف ومتى وأين يشتريه","explain":"«نقداً أم بالأجل» و«فردياً أم في جماعات» = كيف. أيام الأسبوع ونهايته والصبح والمساء والموسم = متى. محلات التجزئة والمراكز التجارية والمنطقة الجغرافية = أين. يحط «بالأجل» تحت متى عشان فيها وقت، أو المنطقة الجغرافية تحت الديموغرافيا.","fix":"شرائح 8–9 — جدول الأسئلة الخمسة.","coach":"اقرأ عليه تفصيلة وحدة كل مرة (بالأجل، المساء، المول، الصيف، ماركة معينة، دافع الراحة) وهو يرد بكلمة السؤال: ما/لماذا/كيف/متى/أين.","sec":"MKT231-CH1"},{"id":"k1.stops-at-purchase","ar":"يحسب الدراسة توقف عند لحظة الشراء","explain":"الشريحة واضحة: الدراسة «لا تتوقف عند مرحلة الشراء»، تكمل لما بعد الشراء (طبيعة الاستخدامات والتقييم) ولين التخلص بـ٦ صور. وبعضهم يخلط «التقييم بعد الاستخدام» مع صور التخلص.","fix":"شريحة 9 + تعريف شريحة 7 (المراحل الخمس).","coach":"خله يرسم خط زمني: بحث ← تقييم ← حصول ← استعمال ← تخلص، ويعد صور التخلص الست على أصابعه.","sec":"MKT231-CH1"},{"id":"k1.importance-vs-growth","ar":"يخلط نقاط الأهمية بأسباب النمو","explain":"القائمتين كل وحدة ١٠ نقاط وشكلهم متقارب. «تصميم الموقع التنافسي» و«اكتشاف الفرص التسويقية المواتية» و«تفهم أدوار أعضاء الأسرة» = أهمية لرجال الأعمال (ش10–11). «قصر دورة حياة المنتج» و«فشل نسبة كبيرة من المنتجات الجديدة» و«النمو المستمر للتسويق الدولي» = أسباب نمو (ش15–16).","fix":"شرائح 10–11 و15–16 — اقرأها جنب بعض.","coach":"اكتب الـ٢٠ نقطة على كروت مخلوطة وخله يفرزها لكومتين: أهمية / أسباب نمو.","sec":"MKT231-CH1"},{"id":"k1.audiences-mixup","ar":"يلخبط بين فئات الأهمية الأربع","explain":"ينسب جمع البيانات بانتظام لطلاب الإدارة، أو تحسين القرارات الشرائية لمسؤولي التسويق. الصح: مسؤولي التسويق = جمع وتحليل البيانات بصفة مستمرة بسبب التغيرات (ش12)؛ طلاب إدارة الأعمال = مديرو المستقبل يستعدون للتطور العلمي والبحثي والتقني (ش13)؛ المستهلكين عامة = يفهمون قراراتهم ويحسنونها (ش14).","fix":"شرائح 10–14 — العناوين الأربعة وجملة مفتاحية لكل واحد.","coach":"اقرأ عليه جملة مفتاحية (التغيرات الاجتماعية المعاصرة / مديري المستقبل / تحسين قراراتهم / تجزئة السوق) واسأله: لمين هذي الفائدة؟","sec":"MKT231-CH1"},{"id":"k1.psych-vs-social","ar":"يخلط علم النفس بالاجتماع والنفس الاجتماعي","explain":"الثلاثة متقاربين بالاسم. علم النفس = دوافع واتجاهات نفسية وتذكر العلامة وصورتها الذهنية. علم الاجتماع = طبقة اجتماعية ودورة حياة الأسرة وقادة الرأي. علم النفس الاجتماعي = بين الاثنين: الفرد داخل الجماعة والتأثير المتبادل وضغوط الجماعة.","fix":"شرائح 17–18.","coach":"اعطه كلمة مفتاحية (صورة ذهنية، طبقة، ضغط الشلة، قائد رأي، تأثير متبادل، دوافع) وهو يرد باسم العلم.","sec":"MKT231-CH1"},{"id":"k1.anthro-vs-demography","ar":"يخلط الثقافات الفرعية بالديموغرافيا","explain":"القيم الجوهرية والمعتقدات والعادات والتقاليد والأقليات العرقية (Subcultures) = دراسة ثقافات الأجناس البشرية (ش19). الدخل والوظيفة والتعليم والسن وحجم الأسرة ومحل الإقامة = الديموغرافيا (ش21).","fix":"شريحة 19 وشريحة 21.","coach":"قل له خاصية (عادات، دخل، معتقدات، سن، أقلية عرقية، محل إقامة، تقاليد) وهو يقول: ثقافات ولا ديموغرافيا.","sec":"MKT231-CH1"},{"id":"k1.econ-vs-home-econ","ar":"يخلط الاقتصاد بالاقتصاد المنزلي والإحصاء","explain":"الاقتصاد = تحليل الطلب وإنفاق الأموال وتقييم البدائل وأقصى إشباع (ش20). الاقتصاد المنزلي = الإنفاق المالي ومعايير شراء الطعام والملبس ولوازم الأطفال (ش21). الإحصاء = أساليب إحصائية لتحليل وتفسير البيانات (ش21).","fix":"شرائح 20–21.","coach":"خله يلخص كل علم بثلاث كلمات: طلب/بدائل/إشباع — أكل/لبس/أطفال — تحليل/تفسير/بيانات.","sec":"MKT231-CH1"},{"id":"k1.always-rational","ar":"يحسب المستهلك دايم رشيد اقتصادياً","explain":"نظرية الرجل الاقتصادي تفترض الرشد وأقصى منفعة، بس الدراسات الحديثة تقول المستهلك «أقل رشداً بالمفهوم الاقتصادي» لأن عنده أهداف نفسية (يستحق السلعة رغم غلاها) واجتماعية (ضغوط أو إعجاب الآخرين). وبعضهم يلخبط النفسي بالاجتماعي.","fix":"شريحة 20.","coach":"اعطه ٤ مواقف (يحجز جناح لأنه يستاهل، يختار منتجع عشان الصور، يقارن الأسعار ويختار الأرخص، يشتري ماركة عشان أصحابه) وهو يصنف: رشيد/هدف نفسي/هدف اجتماعي.","sec":"MKT231-CH1"},{"id":"k1.trends-vs-sciences","ar":"يحسب التسويق الاجتماعي علم من العلوم","explain":"الاتجاهات الحديثة (ش22) فيها «التسويق الاجتماعي» و«المسئولية الاجتماعية والاخلاقية» — كلها فيها كلمة «اجتماعي» فيلخبطها مع علم الاجتماع وعلم النفس الاجتماعي (ش17–18). وبرضو Relationship marketing (التسويق بالعلاقات) غير Social marketing.","fix":"شريحة 22 + شريحة 25 (المصطلحات بالإنجليزي).","coach":"اقرأ عليه ٦ عناوين مخلوطة من الاتجاهات والعلوم وهو يقول: اتجاه حديث ولا علم؛ بعدين يربط كل مصطلح إنجليزي بعربيه.","sec":"MKT231-CH1"},{"id":"k2.inert-vs-inept","ar":"يخلط غير الفعالة مع المرفوضة","explain":"غير الفعالة = ما يشوف في شرائها فايدة (نقص معلومات أو يتصور مزاياها أقل). المرفوضة = يرفضها بسبب تجربة سيئة سابقة أو نصائح الآخرين. والاثنين مع الحيوية فروع المجموعة المعروفة، أما المستبقاه والمستبعدة ففروع الحيوية.","fix":"ارجع للشكل (2-2) شريحة 18 والتعريفات شريحة 19","coach":"اعطه 4 قصص قصيرة (جرب وندم / سمع من خويه وتركها / ما يعرف عنها شي / يتذكرها ويقارنها) وخله يصنف كل وحدة في ثواني.","sec":"MKT231-CH2"},{"id":"k2.conj-vs-disj","ar":"يخلط القاعدة الاقترانية مع الخيارية","explain":"الاقترانية: لازم الحد الأدنى في كل الخواص (و). الخيارية: يكفي الحد الأدنى في أي خاصية بمفردها (أو). الاثنين يطلعون بدائل كثيرة ويحتاجون أسلوب ثاني بعدهم.","fix":"شرائح 26–29 والشكلين (2-4) و(2-5)","coach":"قول له: اقتران = و، خيار = أو. اعطه فندق يحقق خاصية وحدة بس واسأله: يطلع ولا يبقى في كل قاعدة؟","sec":"MKT231-CH2"},{"id":"k2.lexi-vs-elim","ar":"يخلط المعجمي مع أسلوب الحذف","explain":"الاثنين يرتبون الخواص ويبدون بأهم خاصية. المعجمي ياخذ البديل الأعلى مستوى فيها، والحذف يشيل اللي تحت الحد الأدنى ويكمل خاصية ورا خاصية لين يبقى بديل واحد.","fix":"شرائح 30–32 والشكل (2-6)","coach":"خله يشرح الشكل (2-6) بصوته، بعدين اسأله: لو نفس البيانات بأسلوب الحذف، وش يتغير في الطريقة؟","sec":"MKT231-CH2"},{"id":"k2.salient-vs-determinant","ar":"يحسب الهامة هي نفسها الحاسمة","explain":"الهامة Salient = الخواص اللي يعتبرها المستهلك مهمة. الحاسمة Determinant = في مقدمة الهامة، تقود الاختيار وتحسمه لأنها الأهم من كل المعايير.","fix":"شريحة 15","coach":"اسأله: من بين 5 أشياء تهمك في الفندق، أي وحدة لو ما توفرت ما تحجز أبد؟ هذي الحاسمة والباقي هامة.","sec":"MKT231-CH2"},{"id":"k2.involvement-groups","ar":"يحط الأسلوب تحت مجموعة اهتمام غلط","explain":"اهتمام كبير = التعويضي والمرحلي. اهتمام قليل = الشمولية (اقترانية، خيارية، معجمية) والحذف والتكرار. المرحلي فيه أساليب شمولية جواه بس هو نفسه تحت الاهتمام الكبير.","fix":"جدول (2-4) شرائح 22–23","coach":"ارسم الجدول فاضي وخله يعبيه من ذاكرته، وكرر لين يطلع صح مرتين ورا بعض.","sec":"MKT231-CH2"},{"id":"k2.compensatory-vs-holistic","ar":"ما يفرق بين التعويضي والشمولي","explain":"التعويضي: الصفة الممتازة تعوض الصفة المتدنية. الشمولي (غير التعويضي): ياخذ كل الخواص، والممتاز ما يغني عن الرديء.","fix":"شرائح 24–26 والشكل (2-3)","coach":"اسأله عن العلامة (ج) في الشكل (2-3): لو المستهلك يستخدم قاعدة شمولية وحاط حد للسعر، تنقبل ولا تطلع؟","sec":"MKT231-CH2"},{"id":"k2.experiential-mixup","ar":"يخلط الولاء والشعور العام والاندفاعي","explain":"الثلاثة تجريبية وعاطفية. الولاء = اتجاه إيجابي والتزام بالشراء الحين وعزم يكمل مستقبلاً. الشعور العام = يختار اللي يحس نحوه بشعور إيجابي قوي بدون مقارنة خواص. الاندفاعي = شراء مفاجئ غير مخطط بسبب العرض أو تنشيط المبيعات.","fix":"شرائح 34–40","coach":"اعطه 3 مواقف سفر (نفس الخطوط من سنين / منتجع مرتاح له أول مرة / ميدالية عند الكاشير) وخله يسمي كل واحد ويبرر بكلمة.","sec":"MKT231-CH2"},{"id":"k2.urgency-effort","ar":"يحسب الحاجة الماسة تزيد جهد التقييم","explain":"شريحة 16: كلما الحاجة ماسة ← التقييم أقل. أهمية المنتج والمخاطرة المدركة ← التقييم أكبر، وتعقيد البدائل ← التقييم أطول.","fix":"شريحة 16","coach":"اسأله: طيارتك تأخرت وتبي فندق الليلة، بتقارن كثير؟ بعدين خله يسرد التعميمات الأربعة مع اتجاه كل واحد.","sec":"MKT231-CH2"},{"id":"k2.satisfaction-equal","ar":"يحسب الرضا لازم الأداء يتفوق","explain":"الرضا = الأداء الفعلي يساوي التوقعات أو يتفوق عليها. عدم الرضا بس لما الأداء أقل من التوقعات.","fix":"شرائح 45–46","coach":"قول له: توقعت 7 وطلع 7، راضي ولا لا؟ كررها بأرقام 8 و6 لين يثبت.","sec":"MKT231-CH2"},{"id":"k2.source-types","ar":"يلخبط أنواع مصادر المعلومات","explain":"داخلية (خبرته وذاكرته) وخارجية. الخارجية: رسمية غير شخصية (تجارية، حكومية، مستقلة) وغير رسمية شخصية (عائلة، أقارب، أصدقاء). المعلومة المخزنة في الذاكرة داخلية حتى لو أصلها صديق أو إعلان.","fix":"شرائح 12–14","coach":"اعطه أمثلة (بروشور فندق، مجلة المستهلك الخليجية، اتحاد المستهلكين الأمريكي، كلام خويه) وخله يحط كل واحد في الشجرة.","sec":"MKT231-CH2"},{"id":"k2.current-vs-desired","ar":"يخلط تغيرات الحالة الحالية والمرغوبة","explain":"الحالية (3): نضوب المخزون، عدم الرضا عن المخزون الحالي، تناقص الموارد المالية. المرغوبة (4): حاجات جديدة، رغبات جديدة، منتجات جديدة في الأسواق، المنتجات المكملة.","fix":"شرائح 10–11","coach":"علمه سؤال واحد: وش اللي تغير، وضعك أنت ولا اللي تطمح له؟ واعطه 7 مواقف يصنفها.","sec":"MKT231-CH2"},{"id":"k2.stage-step-placement","ar":"يحط الخطوة في المرحلة الغلط","explain":"3 مراحل و7 خطوات: قبل الشراء 4 (الشعور، البحث، التقييم، الاختيار)، الشراء 1 (إتمام الشراء)، بعد الشراء 2 (التقييم أثناء الاستهلاك وبعده، التخلص).","fix":"شرائح 5 و8–9","coach":"اكتب الخطوات السبع على بطاقات مخلوطة وخله يرتبها تحت المراحل الثلاث.","sec":"MKT231-CH2"},{"id":"k2.solving-styles","ar":"يخلط أساليب حل المشكلة الأربعة","explain":"المسهب: أول مرة، مهم، مزايا فريدة، ثمن مرتفع (سيارات، منازل). متوسط المدى: معلومات أقل، مزايا متشابهة (خدمات فندقية). المحدود: الأكثر استخداماً، مخاطرة منخفضة، والاندفاعي أقل أنواعه تعقيداً. الروتيني: بدون بحث ولا مقارنة (خبز، حليب).","fix":"شرائح 53–60","coach":"اعطه منتجات سياحية (شهر عسل، فندق متوسط، شريحة اتصال، قارورة ماء) وخله يحدد الأسلوب ويبرر بسمة وحدة.","sec":"MKT231-CH2"},{"id":"k2.dissonance-vs-dissatisfaction","ar":"يخلط الصراع النفسي مع عدم الرضا","explain":"الصراع النفسي: عدم توازن من معلومات متضاربة بعد قرار الشراء. عدم الرضا: نتيجة التقييم بعد الاستهلاك لما الأداء أقل من التوقعات. لكل واحد قائمته: 6 طرق للتعبير عن عدم الرضا، و7 وسائل لتخفيض الصراع.","fix":"شرائح 45–50","coach":"اسأله: لسا ما جرب الرحلة بس قرأ تقييمات متضاربة، وش اسمها؟ وبعد ما جربها وطلعت أسوأ من توقعه، وش اسمها؟","sec":"MKT231-CH2"},{"id":"k4.position-is-place","ar":"يحسب الموقع التنافسي مكان المحل","explain":"كلمة «موقع» تخدع: الموقع التنافسي مو مكان جغرافي ولا موقع إلكتروني. هو «الصورة أو الفكرة التي تتكون في أذهان المستهلكين عن المنتج بالمقارنة» بالمنافسين.","fix":"ارجع لشريحة 6 (التعريف) وشريحة 9 (وجهان لعملة واحدة).","coach":"اسأله: «وين الموقع التنافسي لفندق فخم تعرفه؟» لو قال عنوان أو مدينة، رجّعه للتعريف: «في راس مين؟ ومقارنةً بمين؟».","sec":"MKT231-CH4"},{"id":"k4.position-vs-image","ar":"يخلط بين الموقع التنافسي والصورة الذهنية","explain":"هم «وجهان لعملة واحدة» بس مو نفس الشي: الموقع اللي تصممه الشركة وتستهدفه (بالمقارنة بالمنافسين)، والصورة الذهنية «التقييم الشخصي للمستهلك للمزايا والفوائد والمنافع...» وهي اللي تتكون فعلاً، وممكن تطابق الموقع أو تختلف عنه.","fix":"شرائح 6 و7 و9.","coach":"اقرأ له تعريف وخلّه يقول «موقع» ولا «صورة» من الكلمة المفتاحية: «بالمقارنة» = موقع، «تقييم شخصي / يتصور» = صورة.","sec":"MKT231-CH4"},{"id":"k4.one-position-only","ar":"يظن المنتج له موقع تنافسي واحد بس","explain":"شريحة 7 تقول ممكن «تحديد مواقع تنافسية مختلفة ومتعددة لنفس المنتج ولكن مع توجيه كل منها لقطاع مختلف من المستهلكين».","fix":"شريحة 7.","coach":"اطلب منه في دقيقة موقعين لنفس المنتجع لقطاعين مختلفين (عوائل / عرسان)، وتأكد إنه يربط كل موقع بقطاع.","sec":"MKT231-CH4"},{"id":"k4.repositioning-scope","ar":"يحسب إعادة التصميم تغيير القطاع والخصائص","explain":"Product Repositioning سببها «الظروف البيئية المتغيرة» وتكون «لنفس القطاع السوقي دون تغيير خصائص العلامة أو ربما مع تحسين أو تغيير احداها». ومن أسباب أهمية الموقع إعادة تصميمه عند مرحلة النضج.","fix":"شريحة 8 + السبب الخامس في شريحة 11.","coach":"سؤالين سريعين: «نفس القطاع ولا قطاع جديد؟» و«كم خاصية ممكن تتغير؟». الجواب: نفس القطاع، وبالكثير وحدة.","sec":"MKT231-CH4"},{"id":"k4.features-not-benefits","ar":"يظن المستهلك يشتري المواصفات التقنية","explain":"قاعدة نابلر: «المستهلكون لا يشترون السلعة من أجل خصائصها الفنية أو التقنية وإنما من أجل منافعها وفوائدها لهم»، فلازم تترجم الخصائص لمنافع. والميزة اللي ما يعتبرها المستهلك مهمة نصرف النظر عنها.","fix":"شرائح 12 و13.","coach":"أعطه خاصية («الفندق فيه ٥٠٠ غرفة») وخلّه يحولها لمنفعة للنزيل بجملة وحدة.","sec":"MKT231-CH4"},{"id":"k4.list-counts","ar":"يلخبط أعداد القوائم في الفصل","explain":"الفصل مليان قوائم متشابهة: قواعد نابلر ٤، شروط الموقع الفعال ٣، خصائص الفرق ٧، أسباب الأهمية ٥، أسباب الضعف ١٢، الاستراتيجيات ٨، طرق التمييز ٤، خطوات التصميم ٦، خطوات الخريطة ٤، فوائد الخريطة ٥.","fix":"جدول «القوائم والأعداد» في الملخص، وشرائح 10–15 و16–17 و30–35.","coach":"بطاقات: اسم القائمة على وجه والعدد على الوجه الثاني، ٣ جولات سريعة لين ما يغلط.","sec":"MKT231-CH4"},{"id":"k4.unique-vs-distinct","ar":"يخلط بين فريد ومتميز وأصيل","explain":"شريحة 14: فريد = «لم يقدمه أحد المنافسين من قبل أو أن تقدمه الشركة للمستهلكين بطريقة جديدة»؛ متميز = «يمتاز على كل الطرق أو الوسائل التي يستخدمها المنافسون في تحقيق منفعة أفضل» (وظيفية أو مالية أو نفسية أو اجتماعية)؛ الأصالة والمبادأة = «يصعب على المنافسين تقليده».","fix":"شريحة 14.","coach":"قل له ٣ جمل: «أول واحد يقدمها» / «أحسن من كل طرق المنافسين» / «صعب تتقلد»، وخلّه يسمي الخاصية لكل جملة.","sec":"MKT231-CH4"},{"id":"k4.weak-looks-good","ar":"يحسب بعض أسباب الضعف أشياء إيجابية","explain":"بعض أسباب الضعف تبان حلوة: «تصميم الموقع التنافسي بحيث يناسب كل الناس»، «الاعتماد كلية على إحدى التقنيات الجديدة»، «التوسع في خط المنتجات» (يشوّش)، و«مهاجمة الموقع التنافسي لعلامة الشركة القائدة». مع إن «المقارنة المباشرة مع المنافسين» استراتيجية سليمة في شريحة 28.","fix":"شريحة 15 مقابل شريحة 13 وشريحة 28.","coach":"اقرأ له ٦ عبارات خليط من شروط وأسباب ضعف واستراتيجيات، وخلّه يصنف كل وحدة: شرط / ضعف / استراتيجية.","sec":"MKT231-CH4"},{"id":"k4.user-vs-psych","ar":"يخلط جماعة المستهلكين بالحاجات النفسية","explain":"الاثنين يجيبون الطبقة العليا. جماعة المستهلكين = ربط العلامة «بفئة محددة من العملاء أو بجماعات المستهلكين الذين ينتمون الى طبقة اجتماعية معينة» (مجوهرات فاخرة، ساعات غالية، أقلام فخمة). الحاجات النفسية = تقدير الذات وتحقيق الذات وعبارات تخاطب الفخامة والطموح (مسيو كازانوفا «الثقة بالنفس»، BMW «مكانك في احضان الفخامة»).","fix":"شريحة 24 مقابل شريحة 27، وصناديق الشكل في شريحة 18.","coach":"سؤال واحد يحسمها: «الإعلان يحدد مين الزبون، ولا يخاطب شعوره وطموحه؟». الأول جماعة، الثاني حاجات نفسية.","sec":"MKT231-CH4"},{"id":"k4.class-vs-use","ar":"يخلط فئة المنتج بطريقة الاستعمال","explain":"طريقة الاستعمال = «يقترح مسئول التسويق طرقاً جديدة أو مبتكرة لاستعمال المنتج» (معلبات في كل الوجبات، بنك بالهاتف والآلات المصرفية). فئة أو نوع المنتج = «استغلال نوع وطبيعة المنتج نفسه» وتفيد لما الشركة تغير تركيب المنتج (قهوة سريعة الذوبان مقابل القهوة العربية).","fix":"شريحة 23 مقابل شريحة 25.","coach":"اسأله: «الإعلان يقترح استعمال جديد؟ ولا يبرز طبيعة نوع المنتج نفسه مقارنة بنوع ثاني؟». وجرّبها على مثال القهوة والمعلبات.","sec":"MKT231-CH4"},{"id":"k4.single-vs-multiple","ar":"يلخبط مثال بركة بمثال نادك","explain":"الفرق الواحد: ميزة وحدة متفوقة تفوق ملموس (مياه بركة خالية من الصوديوم)، وميزته إن المستهلك يتذكر الرسائل اللي تركز على المركز الأول. الفروق المتعددة: لما شركتين أو أكثر تدعي إنها الأفضل في نفس الميزة، فتشير لأكثر من فرق (ألبان نادك: الطعم والجودة).","fix":"شرائح 20 و21.","coach":"ثلاث أسئلة: «بركة كم فرق؟ نادك كم؟ متى نحتاج أكثر من فرق؟».","sec":"MKT231-CH4"},{"id":"k4.price-quality-one-way","ar":"يحسب السعر والجودة اتجاه واحد بس","explain":"شريحة 22: العلاقة تأخذ اتجاهين: السعر المرتفع بجودة مرتفعة (علاقة طردية في ذهن المستهلك، لكزس في خطوط تويوتا)، والسعر المنخفض المرتبط بقيمة كبيرة. ما فيه «سعر عالي بجودة منخفضة».","fix":"شريحة 22.","coach":"خلّه يعطي مثال فندقي أو طيران لكل اتجاه من الاتجاهين.","sec":"MKT231-CH4"},{"id":"k4.steps-order","ar":"يلخبط ترتيب خطوات التصميم والخريطة","explain":"خطوات التصميم ٦: تحليل المنافسة ← مواقع المنافسين (بالخريطة الإدراكية) ← خصائص المستهلكين ← الخصائص الحاسمة ← الاختيار ← المتابعة. وخطوات الخريطة ٤: الاستبانة ← جمع البيانات ← التحليل الإحصائي (القياس متعدد الأبعاد) ← الرسم. لا تخلط القائمتين، والقياس متعدد الأبعاد مو طريقة بحث مستقلة.","fix":"شرائح 30–34.","coach":"اكتب الخطوات على أوراق صغيرة مخلوطة وخلّه يرتب القائمتين مرتين بدون ما يشوف الملخص.","sec":"MKT231-CH4"},{"id":"k4.determinant-attributes","ar":"يظن أي خاصية مهمة تعتبر حاسمة","explain":"شريحة 31: الحاسمة هي اللي يستخدمها المستهلك «في اختيار علامة بعينها دون غيرها»، ولازم شرطين مع بعض: هامة من وجهة نظر المستهلك + يحس باختلافات فيها بين العلامات. والخريطة الإدراكية تنرسم «طبقاً لخصائصها الحاسمة».","fix":"شريحة 31 وشرائح 33–34.","coach":"اسأله: «الأمان في الطيران مهم، بس لو كل الشركات متساوية فيه بنظر المسافر، هل هو حاسم؟» (لا، لأنه ما يفرّق).","sec":"MKT231-CH4"},{"id":"k5.culture-is-psych","ar":"يحسب الثقافة عامل نفسي","explain":"خطة المقرر تحط الفصل تحت القسم الثالث «العوامل البيئية المؤثرة في سلوك المستهلك»، وشريحة 21 تقول الثقافة «من أهم العوامل البيئية». يتلخبط لأن الفصل فيه كلمات زي «التعلم» و«الاتجاهات النفسية»، وهذي عناوين فصول العوامل النفسية.","fix":"شرائح 2–3 و21","coach":"اسأله: الثقافة من أي قسم؟ وخله يعدد العوامل النفسية الأربعة (الدوافع، الإدراك، التعلم، الاتجاهات) ويقول ليش الثقافة مو منها.","sec":"MKT231-CH5"},{"id":"k5.culture-common-usage","ar":"يحسب الاستعمال الشائع يشمل الجانب المادي","explain":"التعريف الكامل للحضارة فيه عنصرين (معنوي ومادي)، بس الشريحة تقول الاستعمال الشائع للكلمة يقصد الجانب المعنوي أو التجريدي فقط دون المادي. يخلط بين التعريف الكامل والاستعمال الشائع، أو يحط السيارات والمباني تحت المعنوي.","fix":"شريحة 6","coach":"اعطه 6 كلمات (مباني، عادات، سيارات، معتقدات دينية، حاسبات، تقاليد) يصنفها معنوي أو مادي، وبعدين اسأله: لما الناس يقولون «ثقافة» عادة وش يقصدون؟","sec":"MKT231-CH5"},{"id":"k5.core-vs-individual","ar":"يخلط القيم الجوهرية بالقيم الفردية","explain":"القيم الجوهرية للمجتمع كله ويؤمن بها جميع أفراده وملزمة لهم، والفردية خاصة بالشخص وما يشاركه فيها باقي المجتمع. يقلب مثال الثوب: لبس الأبيض جوهري، وتصميمه حجازي أو قطري فردي.","fix":"شرائح 8 و24","coach":"قل له أمثلة (صلاة الجمعة، لون الشماغ المفضل، احترام الكبير، ماركة الجوال) وخله يقول جوهرية ولا فردية مع السبب.","sec":"MKT231-CH5"},{"id":"k5.social-vs-consumer-socialization","ar":"يخلط التطبيع الاجتماعي بالتطبيع الاستهلاكي","explain":"التطبيع الاجتماعي = تعلم ثقافة المجتمع والتكيف مع عاداته وحاجاته. التطبيع الاستهلاكي = امتداد له خاص بالسوق: معرفة السوق والدوافع الشرائية والمواقف تجاه الشركات والمحلات والسلع. يحسبهم نفس الشي أو يعكس مين امتداد لمين.","fix":"شرائح 9–10","coach":"اسأله: مين امتداد لمين؟ وخله يذكر 3 أشياء تتشكل في التطبيع الاستهلاكي.","sec":"MKT231-CH5"},{"id":"k5.socialization-childhood-only","ar":"يحسب التطبيع الاجتماعي يخلص بالطفولة","explain":"الشريحة تقول التطبيع الاجتماعي يبدأ في الطفولة و«تستمر طوال حياة الفرد». يمسك كلمة الطفولة وينسى الاستمرار.","fix":"شريحة 9","coach":"صح أو خطأ سريع: «التطبيع الاجتماعي ينتهي بنهاية الطفولة»، وخله يصححها بنص الشريحة.","sec":"MKT231-CH5"},{"id":"k5.characteristics-mixup","ar":"يلخبط الخصائص الأربع للثقافة","explain":"الخصائص الأربع: تعلم الفرد لثقافة مجتمعه، توارثها عبر الأجيال، تكيفها مع التغيير في بعض القيم في الأجل الطويل، وسيلة للإشباع الاجتماعي. يضيف خصائص مو موجودة زي «غريزية» أو «ما تتغير أبداً»، أو ينسى وحدة.","fix":"شرائح 11–15","coach":"خله يكتب الأربع من الذاكرة، وتحت كل وحدة سطر: طرق التعلم الثلاث، مؤسسات التوارث الخمس، دور مدير التسويق، مثال اللحوم والبطاطس.","sec":"MKT231-CH5"},{"id":"k5.satisfaction-vs-change","ar":"يحط مثال اللحوم والبطاطس تحت التكيف","explain":"مثال انصراف الأمريكيين عن اللحوم والبطاطس مذكور تحت الخاصية الرابعة (الإشباع الاجتماعي): العادة ما عادت تشبع حاجة الناس بعد ما كثرت الوظائف المكتبية، فانحسرت. يحطه تحت التكيف مع التغيير لأن فيه تغير.","fix":"شرائح 14–15","coach":"اسأله: ليش الأمريكيين تركوا اللحوم والبطاطس؟ وتحت أي خاصية جا المثال؟ لازم يقول «ما عادت تشبع الحاجة» = الإشباع.","sec":"MKT231-CH5"},{"id":"k5.lists-mixup","ar":"يخلط الجوانب الخمسة بالأسباب والمجالات الثلاثة","explain":"الفصل فيه 3 قوائم متشابهة: الجوانب الخمسة لتأثير الثقافة على المستهلك (ش16)، أسباب الشراء الثلاثة تحت الجانب الثالث (ش19–20)، ومجالات استفادة مدير التسويق الثلاثة (ش36–37). يجيب بند من قائمة كإجابة لسؤال عن قائمة ثانية.","fix":"شرائح 16، 19–20، 36–37","coach":"اكتب البنود الـ11 على بطاقات مخلوطة وخله يوزعها على القوائم الثلاث.","sec":"MKT231-CH5"},{"id":"k5.three-reasons-mixup","ar":"يلخبط بين الأداء الوظيفي والهيئة والرموز","explain":"الأداء الوظيفي = المهمة المتوقعة ومستواها (جودة المنتجات اليابانية)، الهيئة = الشكل اللي تنستهلك فيه السلعة (سمك نيئ أو مطهي)، الرموز الحضارية = وش تعني السلعة للمجتمع (الكبسة، العزايم). يخلط مثالي اليابان لأنها موجودة في الأداء والهيئة.","fix":"شرائح 19–20","coach":"قل له: كاميرا يابانية، سوشي، كبسة، عزيمة عرس، وخله يحدد السبب لكل وحدة.","sec":"MKT231-CH5"},{"id":"k5.islamic-vs-western","ar":"يقلب فلسفة الاستهلاك بين الغرب والإسلام","explain":"الغربية: رفاهية مادية وتعظيم الاستهلاك الاستمتاعي، والأمريكية تشجع التنافس والمصلحة الشخصية. الإسلامية: تقلل المبالغة في الاستمتاع المادي وتطلب توازن مع الروحي، ومعها اليابانية تقدم مصلحة الجماعة. يقلبها أو يحط اليابانية مع الأمريكية.","fix":"شرائح 17، 21، 28","coach":"جدول من 3 أعمدة (إسلامي، أمريكي، ياباني) يعبيه من الذاكرة وبعدين يقارنه بالشرائح.","sec":"MKT231-CH5"},{"id":"k5.terminal-vs-instrumental","ar":"يعكس دور القيم النهائية والوسيطة","explain":"النهائية = الغايات وتأثر في الاختيار بين فئات المنتجات؛ الوسيطة = الوسائل وتأثر في الاختيار بين العلامات التجارية. وكل مجموعة 18 قيمة (36 بالمجموع). يعكس الدور أو يقول 18 بالمجموع.","fix":"شرائح 24–25","coach":"اسأله: «أبي أرتاح» نهائية ولا وسيطة؟ «أكون ملتزم بالمواعيد»؟ وبعدين: أي وحدة تحدد الفئة وأي وحدة تحدد الماركة؟","sec":"MKT231-CH5"},{"id":"k5.three-institutions-four-items","ar":"يعد ثقافة الاستهلاك مؤسسة رابعة","explain":"شريحة 30 تقول التغيرات تجتاح ثلاث مؤسسات: الأسرة والدين والتعليم، بس البنود بعدها مرقمة 4، والرابع «التحول الى ثقافة الاستهلاك» مو مؤسسة. ويخلطها كمان مع مؤسسات توارث الثقافة (أسرة، مدرسة، جامعة، دينية، إعلام).","fix":"شرائح 13، 30–35","coach":"اسأله: كم مؤسسة في شريحة 30؟ كم بند مرقم؟ ووش الفرق بينها وبين قائمة شريحة 13؟","sec":"MKT231-CH5"},{"id":"k5.change-values","ar":"يحسب التسويق لازم يغير قيم المجتمع","explain":"شريحة 25: الاستراتيجية التسويقية الفعالة لازم «تعكس تلك القيم بدلاً من أن تحاول تغييرها»، وشريحة 14: مدير التسويق يراقب التغير ويكيّف استراتيجيته معه. يحسب دور التسويق تغيير القيم.","fix":"شرائح 14 و25","coach":"اعطه موقف: شركة تبي تبيع منتج يخالف قيم المجتمع، وش تسوي حسب الشرائح؟","sec":"MKT231-CH5"},{"id":"k5.marketing-areas-mixup","ar":"يلخبط مجالات مدير التسويق الثلاثة","explain":"المجال 1 تصميم المنتجات واستخداماتها (الخلطات والإعداد ووقت التناول)، المجال 2 خلق تصور إيجابي (الدواجن المذبوحة إسلامياً في الإعلان والعبوة)، المجال 3 فهم طرق الاتصال والعلاقات (التسويق الدولي للمنشآت السعودية). يحط مثال الدواجن تحت التصميم.","fix":"شرائح 36–37","coach":"3 مواقف سياحية (منيو رمضاني، إعلان «حلال 100%»، مكتب سياحي في طوكيو) وخله يربط كل موقف بمجاله.","sec":"MKT231-CH5"},{"id":"k6.status-class-reversed","ar":"تقلبها: تحسب المركز هو اللي يحدد الطبقة","explain":"ش7 تقول الطبقة اللي ينتمي لها الفرد تحدد مركزه الاجتماعي، والمركز بعدين يعكس توقعات المجتمع لأسلوب المعيشة مقارنة بالطبقات الثانية + الاحترام. الاتجاه: طبقة ← مركز ← توقعات واحترام.","fix":"اقرأ ش6–7 وركز على الكلمتين الحمر «تحدد» و«المركز الاجتماعي».","coach":"ارسم سهم: طبقة ← تحدد ← مركز ← يعكس (توقعات + احترام). غطه وأعد رسمه من الذاكرة مرتين.","sec":"MKT231-CH6"},{"id":"k6.absolute-stability","ar":"تحسب الطبقة ثابتة ما تتغير أبداً","explain":"الثبات «نسبي»: الأبناء في أغلب الأحوال بطبقة الآباء، بس الأسرة العادية تقدر تنتقل لو توفرت لها الظروف المواتية، والانتقال مو بنفس السهولة في كل المجتمعات.","fix":"ش7، الفقرة الثانية.","coach":"قل 3 كلمات بصوت: غالباً – ممكن – مو بنفس السهولة. وأي خيار فيه «أبداً» أو «بنفس السهولة في كل العالم» اشطبه.","sec":"MKT231-CH6"},{"id":"k6.personal-vs-others","ar":"تخلط بين الحكم الشخصي والحكم على الآخرين","explain":"الحكم الشخصي = الفرد يصنف نفسه باستبانة بسيطة. الحكم على الآخرين = الباحث يسند التصنيف لمجموعة منتقاة يثق في خبرتهم. السؤال الحاسم: مين يصنف؟","fix":"ش11 و ش12.","coach":"لكل سيناريو اسأل: مين صنّف؟ هو نفسه = شخصي، ناس ثانيين = على الآخرين، متغيرات وأرقام = موضوعي. جرب 3 أمثلة من عندك.","sec":"MKT231-CH6"},{"id":"k6.questionnaire-trap","ar":"تحسب أي استبانة تعني حكم شخصي","explain":"الاستبانة موجودة في الحكم الشخصي (استبانة بسيطة يحدد فيها الفرد طبقته بنفسه) وفي القياس الموضوعي (استبانات تجمع الوظيفة والدخل والثروة والتعليم). الفرق في وش تسأل الاستبانة ومين يصنف.","fix":"قارن ش11 مع ش13.","coach":"اكتب سؤالين: «من أي طبقة أنت؟» و«وش وظيفتك وكم دخلك؟». سمّ الطريقة لكل سؤال.","sec":"MKT231-CH6"},{"id":"k6.others-flawless","ar":"تحسب الحكم على الآخرين ما فيه عيوب","explain":"صح تتلافى مساوئ الحكم الشخصي، بس لها مشكلتين: المصنفين ما يزالون يستخدمون حكمهم الشخصي، وتتطلب مجتمع صغير مغلق يعرف فيه المصنفين باقي الأفراد معرفة جيدة.","fix":"ش12 من «إلا أن» لآخر الشريحة.","coach":"احفظ «صغير مغلق + لسا شخصي». واسأل نفسك: تنفع في الرياض؟ لا، ليش؟","sec":"MKT231-CH6"},{"id":"k6.single-vs-multi","ar":"تخلط بين المتغير الواحد والمتغيرات المتعددة","explain":"القياس الموضوعي نوعين: ذات المتغير الواحد (الوظيفة أو التعليم أو الدخل أو متغيرات ثانية، كل واحد لحاله) وذات المتغيرات المتعددة (4 مؤشرات: وارنر، هولنجزهد، الحكومة الأمريكية، كولمان). الاثنين جوا القياس الموضوعي، مو مجموعات مستقلة جنب الحكم الشخصي.","fix":"ش14 و ش17 + الشجرة في أول الملخص.","coach":"ارسم الشجرة من الذاكرة: 3 مجموعات ← الموضوعي يتفرع لـ2 ← المتعددة تتفرع لـ4.","sec":"MKT231-CH6"},{"id":"k6.secondary-vars-alone","ar":"تحسب المسكن والممتلكات تكفي لحالها للحكم","explain":"جودة المنطقة السكنية وقيمة المسكن المملوك والممتلكات الشخصية ممكن تستخدم منفردة، بس «نادراً ما تستخدم هذه المتغيرات وحدها»، ودورها وسيلة إضافية للتأكد من تصنيف طلع من مؤشر ثاني زي المركز الوظيفي أو الدخل.","fix":"ش16 الجزء الثاني.","coach":"قل: «نادراً وحدها، غالباً للتأكد». وعدّ الثلاثة على أصابعك: منطقة، مسكن، ممتلكات.","sec":"MKT231-CH6"},{"id":"k6.warner-income-amount","ar":"تحسب وارنر يستخدم مقدار الدخل","explain":"الشريحة نفسها تنبه: «لاحظ أن مؤشر وارنر يستخدم مصدر الدخل وليس مقداره». الدخل عموماً له طريقتين (ش16): مقدار ومصدر، ووارنر أخذ المصدر بوزن 3 وحدات.","fix":"ش16 (طريقتين الدخل) + ش18.","coach":"اكتب أوزان وارنر 4-3-2-1 واكتب جنب الـ3 كلمة «مصدر» بخط كبير. كررها لين تطلع لحالها.","sec":"MKT231-CH6"},{"id":"k6.index-numbers-mixup","ar":"تلخبط سنوات وأوزان وارنر وهولنجزهد","explain":"وارنر 1941: الوظيفة 4، مصدر الدخل 3، نوع المسكن 2، جودة المنطقة 1، ست طبقات. هولنجزهد 1958: المسكن 6، الوظيفة 9، التعليم 5، خمس طبقات «وليس ستاً». وارنر ما فيه تعليم، وهولنجزهد ما فيه دخل.","fix":"ش18–19 + جدول المقارنة في الملخص.","coach":"اكتب سطرين من الذاكرة: «41 – 4 متغيرات – 4321 – 6» و«58 – 3 متغيرات – 6/9/5 – 5». كررها 3 مرات.","sec":"MKT231-CH6"},{"id":"k6.usgov-vs-coleman","ar":"تخلط مقياس الحكومة الأمريكية مع كولمان","explain":"الحكومة الأمريكية: 3 متغيرات (الوظيفة، دخل الأسرة مع الزوجة والأولاد لو يشتغلون، التعليم)، وهو الأكثر قبولاً واستخداماً بين مديري التسويق. كولمان: لسكان المدينة، 6 متغيرات فيها وظيفة وتعليم الزوج والزوجة، المنطقة، المسكن، المؤسسة الدينية، والمؤسسات الاجتماعية المحلية، وما فيه دخل.","fix":"ش20–21.","coach":"اختبر نفسك بسؤالين: وين يجي دخل الزوجة؟ (الحكومة). وين تجي وظيفة الزوجة؟ (كولمان).","sec":"MKT231-CH6"},{"id":"k6.scale-extremes-only","ar":"تحسب المقياس يكفي يميز بين المتطرفين","explain":"ش22: المقياس لازم يميز «بين الحالات القريبة جداً من بعضها على السلم الاجتماعي وليس فقط بين الحالات المتطرفة». وباقي الشروط: الطبقة الحقيقية، العينة المناسبة، الموضوعية، نفس الترتيب لو تكرر، الدقة رغم التغيرات.","fix":"ش22.","coach":"عدّ الشروط الستة بالكلمات: حقيقية، عينة، موضوعية، تمييز، تكرار، دقة. واشرح كل وحدة بجملة.","sec":"MKT231-CH6"},{"id":"k6.strategy-stage-order","ar":"تلخبط ترتيب مراحل الإستراتيجية الأربع","explain":"الترتيب: 1 تحديد العلاقة بين المكانة الاجتماعية واستهلاك المنتج (دراسة الأنماط)، 2 تحديد الطبقات المستهدفة (تصنيف، حجم وقوة شرائية، مراجعة الموارد)، 3 تصميم الموقع التنافسي، 4 إعداد الخطة التسويقية (المزيج).","fix":"ش23–26.","coach":"احفظ «علاقة ← استهداف ← موقع ← خطة». وحط كل نشاط في مرحلته: مراجعة الموارد؟ توقيت الاستعمال؟ التسعير؟","sec":"MKT231-CH6"},{"id":"k6.one-mix-for-all","ar":"تحسب مزيج تسويقي واحد يكفي كل الطبقات","explain":"ش26: «يراعي أن يعد مزيج تسويقي خاص لكل طبقة اجتماعية على حدة»، والعناصر الأربعة (المنتجات، التسعير، الترويج، التوزيع) جوا كل مزيج لازم تتناسق مع احتياجات الطبقة وعاداتها. وش9 كمان تقول البرامج تتلاءم مع رغبات وأذواق «كل منها».","fix":"ش26 و ش9.","coach":"اختار فندق وسوّ له مزيجين: واحد للطبقة العليا وواحد للمتوسطة، وكل مزيج فيه 4 عناصر.","sec":"MKT231-CH6"}],"cases":[],"questions":[{"n":101,"lo":"CH1","sec":"MKT231-CH1","type":"term","topic":"أنواع المستهلك","stem":"«أي فرد يشتري السلع والخدمات إما للاستعمال الشخصي كشراء ملابسه أو للاستهلاك العائلي مثل شراء المواد الغذائية للأسرة» — هذا تعريف:","options":["المستهلك التنظيمي","العميل (Customer)","المستهلك الفردي أو النهائي","قادة الرأي الاستهلاكي"],"answer":2,"why":"شريحة 6: هذا نص تعريف المستهلك الفردي أو النهائي، وعشان شراءه هدفه الاستهلاك النهائي يسمونهم «المستهلكين النهائيين».","wrong":[{"i":0,"mis":"k1.family-is-org","note":"التنظيمي منشآت ومؤسسات وهيئات تشتري عشان تؤدي وظائفها، مو فرد يشتري لنفسه أو لأسرته."},{"i":1,"mis":"gen.neighbor","note":"العميل مذكور في المصطلحات (ش23) بس الشرائح ما عرفته بهذا النص."},{"i":3,"mis":"gen.neighbor","note":"قادة الرأي يجون تحت علم الاجتماع (ش17)، مو نوع من أنواع المستهلك."}],"tests":["المستهلك الفردي أو النهائي","أنواع المستهلك"]},{"n":102,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"أنواع المستهلك","stem":"جمعية خيرية في المدينة استأجرت باصات وحجزت فندق عشان رحلة أيتام لمدة يومين. حسب شريحة 6، الجمعية هنا تعتبر:","options":["مستهلك فردي أو نهائي لأنها تشتري للاستهلاك النهائي","مستهلك تنظيمي","مستهلك عائلي لأنها تخدم مجموعة أطفال","ما تعتبر مستهلك لأنها لا تستهدف الربح"],"answer":1,"why":"شريحة 6: المستهلك التنظيمي يشمل «الهيئات غير التجارية التي لا تستهدف الربح كالجمعيات الخيرية»، وتشتري عشان تؤدي وظائفها وتحقق أهدافها التنظيمية.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الفردي لازم يكون فرد يشتري لنفسه أو لأسرته، والجمعية مو فرد."},{"i":2,"mis":"k1.family-is-org","note":"ما فيه نوع اسمه «مستهلك عائلي»؛ الاستهلاك العائلي جزء من تعريف الفردي، والجمعية مو أسرة."},{"i":3,"mis":"k1.org-means-profit","note":"التعريف نفسه يدخّل الجهات اللي ما تستهدف الربح، والجمعيات الخيرية هي مثال الشريحة."}],"tests":["المستهلك التنظيمي","مكونات المستهلك التنظيمي"]},{"n":103,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"تعريف سلوك المستهلك","stem":"حسب تعريف سلوك المستهلك في شريحة 7، الأنشطة والتصرفات تكون أثناء أي مراحل؟","options":["البحث والشراء فقط","الشراء والاستعمال فقط","البحث والتقييم والشراء، وتنتهي عند الدفع","البحث والتقييم والحصول والاستعمال والتخلص"],"answer":3,"why":"شريحة 7: الأنشطة تكون «أثناء بحثهم عن السلع والخدمات… وأثناء تقييمهم لها والحصول عليها واستعمالها والتخلص منها» — يعني ٥ مراحل، ومعها عمليات اتخاذ القرارات.","wrong":[{"i":0,"mis":"gen.partial","note":"ناقص التقييم والاستعمال والتخلص."},{"i":1,"mis":"gen.partial","note":"ناقص البحث والتقييم والتخلص."},{"i":2,"mis":"k1.stops-at-purchase","note":"السلوك ما يخلص عند الدفع؛ يكمل للاستعمال والتخلص."}],"tests":["تعريف سلوك المستهلك","مراحل سلوك المستهلك"]},{"n":104,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"الافتراضات الضمنية","stem":"أسرة سعودية جلست مع بعض وقررت تقضي الإجازة الصيفية في الخارج. حسب الافتراضات الضمنية في شريحة 7، هذا القرار:","options":["قرار شرائي جماعي","قرار شرائي فردي لأن الأب هو اللي يدفع","نشاط بدني فقط","سلوك اعتباطي ما يوجهه هدف"],"answer":0,"why":"شريحة 7، الافتراض الأول: القرار قد يكون فردي أو جماعي، و«جماعية مثل اتخاذ قرار الأسرة بقضاء الأجازة الصيفية بالخارج».","wrong":[{"i":1,"mis":"k1.individual-vs-group","note":"مثال الفردي في الشريحة شراء كتاب؛ قرار الأسرة بالإجازة هو مثال الجماعي بالنص."},{"i":2,"mis":"k1.physical-vs-mental","note":"اتخاذ القرار الشرائي نشاط ذهني، مو بدني."},{"i":3,"mis":"k1.behavior-random","note":"الافتراض الثالث: السلوك مو اعتباطي في أغلب الأحوال، يوجهه هدف."}],"tests":["القرار الفردي والجماعي","الافتراضات الضمنية"]},{"n":105,"lo":"CH1","sec":"MKT231-CH1","type":"tf","topic":"الأنشطة البدنية والذهنية","stem":"حسب شريحة 7، «جمع المعلومات اللازمة» و«التحدث مع رجال البيع» من الأنشطة الذهنية في سلوك المستهلك.","options":["صح","خطأ"],"answer":1,"why":"خطأ — شريحة 7 تحطهم تحت الأنشطة البدنية مع التسوق. الذهنية هي تحليل المعلومات والمقارنة بينها واتخاذ القرار الشرائي.","wrong":[{"i":0,"mis":"k1.physical-vs-mental","note":"كلمة «معلومات» تغش: الجمع حركة (بدني)، والتحليل تفكير (ذهني)."}],"tests":["الأنشطة البدنية","الأنشطة الذهنية"]},{"n":106,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"طبيعة دراسة سلوك المستهلك","stem":"باحث في شركة سياحة يدرس: هل العملاء يدفعون قيمة الباقة نقداً أم بالأجل؟ وهل يحجزون فردياً أم في جماعات؟ هذا يجاوب على أي عبارة من عناصر دراسة سلوك المستهلك؟","options":["متى يشتريه","لماذا يشتريه","كيف يشتريه","أين يشتريه"],"answer":2,"why":"شريحة 8: «كيف يشتريه» تشير «إلى الكيفية التي يتم بها الشراء، سواء كان الشراء يتم نقداً أم بالأجل. وسواء كان فردياً أم في جماعات».","wrong":[{"i":0,"mis":"k1.five-questions-mixup","note":"متى = زمن الشراء: أيام الأسبوع أو نهايته، صباح أو مساء، والموسم."},{"i":1,"mis":"k1.five-questions-mixup","note":"لماذا = الدوافع والأسباب الكامنة ورا القرار الشرائي."},{"i":3,"mis":"k1.five-questions-mixup","note":"أين = محلات التجزئة والمراكز التجارية والمنطقة الجغرافية."}],"tests":["الأسئلة الخمسة","كيف يشتريه"]},{"n":107,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"التخلص من السلعة","stem":"يهتم باحثو المستهلك بما يفعله المستهلك بالسلعة بعد الانتهاء من استخدامها. أي من التالي من صور التخلص اللي ذكرتها شريحة 9؟","options":["يقيّمونها بعد استخدامها","يقرضونها لشخص آخر بهدف الاستخدام المؤقت","يقارنونها بالعلامات التجارية الأخرى","يشترونها نقداً أم بالأجل"],"answer":1,"why":"شريحة 9: صور التخلص ٦ — يخزنونها، يلقونها في القمامة، يعطونها لشخص آخر، يبيعونها، يؤجرونها لفرد آخر، أو «يقرضونها لشخص آخر بهدف الاستخدام المؤقت».","wrong":[{"i":0,"mis":"k1.stops-at-purchase","note":"التقييم بعد الاستخدام من مرحلة ما بعد الشراء، مو صورة تخلص."},{"i":2,"mis":"k1.physical-vs-mental","note":"المقارنة نشاط ذهني قبل القرار (ش7)."},{"i":3,"mis":"k1.five-questions-mixup","note":"هذا معنى «كيف يشتريه» (ش8)."}],"tests":["صور التخلص من السلعة","ما بعد الشراء"]},{"n":108,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"أهمية الدراسة لرجال الأعمال","stem":"أي من التالي من نقاط أهمية دراسة سلوك المستهلك لرجال الأعمال ومديري الشركات (شرائح 10–11)؟","options":["قصر دورة حياة المنتج","فشل نسبة كبيرة من المنتجات الجديدة","النمو المستمر للتسويق الدولي","تصميم الموقع التنافسي المناسب لمنتجات الشركة"],"answer":3,"why":"شريحة 11: النقطة ٦ من أهمية الدراسة لرجال الأعمال هي «تصميم الموقع التنافسي المناسب لمنتجات الشركة». الباقي أسباب نمو.","wrong":[{"i":0,"mis":"k1.importance-vs-growth","note":"سبب نمو رقم ٣ (ش15)."},{"i":1,"mis":"k1.importance-vs-growth","note":"سبب نمو رقم ٢ (ش15)."},{"i":2,"mis":"k1.importance-vs-growth","note":"سبب نمو رقم ٩ (ش16)."}],"tests":["أهمية الدراسة لرجال الأعمال ومديري الشركات"]},{"n":109,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"أسباب نمو سلوك المستهلك","stem":"واحد من التالي من الأسباب الرئيسية لنمو سلوك المستهلك (شرائح 15–16):","options":["اكتشاف الفرص التسويقية المواتية","تفهم أدوار أعضاء الأسرة في عملية اتخاذ القرار","الاهتمام المتزايد بوظيفة التسويق من جانب التنظيمات غير الهادفة للربح","التأثير في الاتجاهات النفسية للمستهلكين"],"answer":2,"why":"شريحة 16: السبب ٨ هو «الاهتمام المتزايد بوظيفة التسويق من جانب التنظيمات غير الهادفة للربح». الخيارات الباقية من أهمية الدراسة لرجال الأعمال.","wrong":[{"i":0,"mis":"k1.importance-vs-growth","note":"نقطة أهمية رقم ١ لرجال الأعمال (ش10)."},{"i":1,"mis":"k1.importance-vs-growth","note":"نقطة أهمية رقم ٧ (ش11)."},{"i":3,"mis":"k1.importance-vs-growth","note":"نقطة أهمية رقم ٥ (ش10)."}],"tests":["الأسباب الرئيسية لنمو سلوك المستهلك"]},{"n":110,"lo":"CH1","sec":"MKT231-CH1","type":"tf","topic":"فئات أهمية الدراسة","stem":"حسب الشرائح 10–14، أهمية دراسة سلوك المستهلك موزعة على أربع فئات: رجال الأعمال ومديري الشركات، ومسؤولي التسويق، وطلاب إدارة الأعمال، والمستهلكين عامة.","options":["صح","خطأ"],"answer":0,"why":"صح — ش10: لرجال الأعمال ومديري الشركات، ش12: لمسؤولي التسويق، ش13: لطلاب إدارة الأعمال، ش14: للمستهلكين عامة.","wrong":[{"i":1,"mis":"k1.audiences-mixup","note":"الفئات فعلاً أربع؛ شريحة 12 عنوانها بدون رقم بس هي الفئة الثانية."}],"tests":["فئات أهمية دراسة سلوك المستهلك"]},{"n":111,"lo":"CH1","sec":"MKT231-CH1","type":"concept","topic":"العلوم الاجتماعية","stem":"دراسة العوامل اللي تزيد تذكّر المستهلك للعلامة التجارية، والصورة الذهنية للعلامة في أذهان المستهلكين — هذا من إسهامات:","options":["علم الاجتماع","علم النفس","علم النفس الاجتماعي","علم الإحصاء"],"answer":1,"why":"شريحة 17: علم النفس يستخدم في دراسة دوافع الشراء والاتجاهات النفسية نحو العلامة «والعوامل التي تؤدي الى زيادة تذكر المستهلك للعلامة التجارية والصورة الذهنية للعلامة».","wrong":[{"i":0,"mis":"k1.psych-vs-social","note":"علم الاجتماع = طبقة اجتماعية، دورة حياة الأسرة، قادة الرأي."},{"i":2,"mis":"k1.psych-vs-social","note":"علم النفس الاجتماعي = الفرد داخل الجماعة وضغوطها."},{"i":3,"mis":"gen.neighbor","note":"الإحصاء أداة لتحليل وتفسير البيانات، مو دراسة الصورة الذهنية."}],"tests":["علم النفس"]},{"n":112,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"العلوم الاجتماعية","stem":"باحث يدرس كيف يختلف اختيار الوجهة السياحية حسب الطبقة الاجتماعية للمسافر، والمرحلة اللي تمر فيها أسرته في دورة حياة الأسرة، ومدى تأثره بقادة الرأي الاستهلاكي. هذا الباحث يستفيد من:","options":["علم النفس الاجتماعي","علم الديموغرافيا","دراسة ثقافات الأجناس البشرية","علم الاجتماع"],"answer":3,"why":"شريحة 17: علم الاجتماع يدرس تأثير الظروف الاجتماعية «مثل انتمائه لطبقة اجتماعية معينة والمرحلة التي يمر بها في دورة حياة الاسرة ومدى تأثره بقادة الرأي الاستهلاكي».","wrong":[{"i":0,"mis":"k1.psych-vs-social","note":"النفس الاجتماعي = الفرد داخل الجماعة والتأثير المتبادل والضغوط."},{"i":1,"mis":"k1.anthro-vs-demography","note":"الديموغرافيا = دخل، وظيفة، تعليم، سن، حجم أسرة، محل إقامة — مو الطبقة ولا دورة حياة الأسرة."},{"i":2,"mis":"k1.anthro-vs-demography","note":"الثقافات = قيم ومعتقدات وعادات وتقاليد وأقليات عرقية."}],"tests":["علم الاجتماع","قادة الرأي الاستهلاكي"]},{"n":113,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"العلوم الاجتماعية","stem":"سعد كان يبغى يسافر المالديف، بس شلته كلهم ضغطوا عليه يروح معهم جورجيا، فغيّر رأيه وراح معهم. دراسة هذي الضغوط من الجماعة اللي ينتمي لها الفرد تتبع:","options":["علم النفس الاجتماعي","علم النفس","علم الاقتصاد","علم الاقتصاد المنزلي"],"answer":0,"why":"شريحة 18: علم النفس الاجتماعي يدرس سلوك الفرد داخل الجماعة، ومنه يهتم الباحثون «بدراسة التأثيرات والضغوط الاجتماعية… من جانب الأفراد الأخرين داخل الجماعات التي ينتمون اليها».","wrong":[{"i":1,"mis":"k1.psych-vs-social","note":"علم النفس يركز على الفرد من داخله (دوافع، صورة ذهنية)، مو ضغط الجماعة."},{"i":2,"mis":"k1.always-rational","note":"الاقتصاد يحلل الطلب وتقييم البدائل وأقصى إشباع، مو ضغوط الشلة."},{"i":3,"mis":"k1.econ-vs-home-econ","note":"الاقتصاد المنزلي = إنفاق البيت ومعايير شراء الطعام والملبس ولوازم الأطفال."}],"tests":["علم النفس الاجتماعي"]},{"n":114,"lo":"CH1","sec":"MKT231-CH1","type":"term","topic":"العلوم الاجتماعية","stem":"دراسة المعتقدات والقيم الخاصة بالأقليات العرقية اللي تعيش داخل المجتمع (Subcultures: الثقافات الفرعية) تتبع أي علم؟","options":["علم الاجتماع (Sociology)","علم الديموغرافيا (Demography)","دراسة ثقافات الأجناس البشرية (Cultural Anthropology)","علم النفس الاجتماعي (Social Psychology)"],"answer":2,"why":"شريحة 19: دراسة ثقافات الأجناس البشرية تهتم بالقيم والمعتقدات والعادات والتقاليد الخاصة بالشعوب، «وكذلك دراسة المعتقدات والقيم الخاصة بالأقليات العرقية… (Subcultures): الثقافات الفرعية».","wrong":[{"i":0,"mis":"gen.neighbor","note":"علم الاجتماع = طبقة، دورة حياة الأسرة، قادة الرأي."},{"i":1,"mis":"k1.anthro-vs-demography","note":"الديموغرافيا خصائص سكانية (دخل، سن…)، مو قيم ومعتقدات."},{"i":3,"mis":"k1.psych-vs-social","note":"النفس الاجتماعي = الفرد داخل الجماعة والتأثير المتبادل."}],"tests":["دراسة ثقافات الأجناس البشرية","الثقافات الفرعية"]},{"n":115,"lo":"CH1","sec":"MKT231-CH1","type":"scenario","topic":"علم الاقتصاد","stem":"خالد حجز جناح فاخر في منتجع بالعلا رغم غلاه الكبير، وقال: «تعبت طول السنة وأنا أستاهل». حسب شريحة 20، تصرفه يوضح:","options":["تصرف رشيد لتحقيق أقصى منفعة ممكنة حسب نظرية الرجل الاقتصادي","تصرف أقل رشداً بالمفهوم الاقتصادي لتحقيق هدف نفسي","تصرف لتحقيق هدف اجتماعي بسبب ضغوط الآخرين","نشاط بدني من أنشطة سلوك المستهلك"],"answer":1,"why":"شريحة 20: الدراسات الحديثة تقول المستهلك يتصرف «بطريقة أقل رشداً» لأهداف غير اقتصادية، منها «شعوره بأنه يستحق شراء سلعة ما بصرف النظر عن ارتفاع ثمنها(هدف نفسي)».","wrong":[{"i":0,"mis":"k1.always-rational","note":"الرجل الاقتصادي يحسبها صح لأقصى منفعة؛ خالد دفع الغالي لأنه «يستاهل»، يعني دافع نفسي."},{"i":2,"mis":"gen.neighbor","note":"الهدف الاجتماعي = ضغوط اجتماعية أو زيادة إعجاب الآخرين، وخالد ما ذكر أحد."},{"i":3,"mis":"k1.physical-vs-mental","note":"هذا دافع وقرار، مو نشاط بدني زي التسوق أو جمع المعلومات."}],"tests":["علم الاقتصاد","نظرية الرجل الاقتصادي","الهدف النفسي والاجتماعي"]},{"n":116,"lo":"CH1","sec":"MKT231-CH1","type":"tf","topic":"العلوم الاجتماعية","stem":"علم الإحصاء يهتم بدراسة طبيعة الإنفاق المالي للمستهلكين ومعايير الشراء الخاصة بالطعام والملبس ولوازم الأطفال.","options":["صح","خطأ"],"answer":1,"why":"خطأ — هذا تعريف علم الاقتصاد المنزلي (ش21). الإحصاء «يشمل الاستعانة بالأساليب الاحصائية في تحليل وتفسير البيانات الخاصة بسلوك المستهلك».","wrong":[{"i":0,"mis":"k1.econ-vs-home-econ","note":"الطعام والملبس ولوازم الأطفال = الاقتصاد المنزلي؛ الإحصاء أداة تحليل بيانات."}],"tests":["علم الاقتصاد المنزلي","علم الإحصاء"]},{"n":117,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"علم الديموغرافيا","stem":"أي من التالي من الخصائص الديموغرافية للسكان اللي ذكرتها شريحة 21؟","options":["القيم الجوهرية","الصورة الذهنية للعلامة","دوافع الشراء","محل الإقامة"],"answer":3,"why":"شريحة 21: الخصائص الديموغرافية «مثل الدخل والوظيفة ومستوى التعليم والسن وحجم الأسرة ومحل الإقامة» — ٦ خصائص.","wrong":[{"i":0,"mis":"k1.anthro-vs-demography","note":"القيم الجوهرية من دراسة ثقافات الأجناس البشرية (ش19)."},{"i":1,"mis":"gen.neighbor","note":"الصورة الذهنية من علم النفس (ش17)."},{"i":2,"mis":"gen.neighbor","note":"دوافع الشراء من علم النفس (ش17)."}],"tests":["علم الديموغرافيا","الخصائص الديموغرافية"]},{"n":118,"lo":"CH1","sec":"MKT231-CH1","type":"list","topic":"الاتجاهات الحديثة","stem":"أي من التالي من الاتجاهات الحديثة في سلوك المستهلك (شريحة 22)؟","options":["حقوق ملكية العلامة التجارية Brand Equity","علم النفس الاجتماعي Social Psychology","قصر دورة حياة المنتج","تجزئة السوق وتقييمه واختيار القطاعات المربحة"],"answer":0,"why":"شريحة 22: الاتجاهات الحديثة ٦، منها «حقوق ملكية العلامة التجارية Brand Equity» مع تسويق الخدمات وCustomer value وRelationship marketing وSocial marketing والمسئولية الاجتماعية والأخلاقية.","wrong":[{"i":1,"mis":"k1.trends-vs-sciences","note":"هذا علم من العلوم الاجتماعية (ش18)، مو اتجاه حديث."},{"i":2,"mis":"gen.neighbor","note":"سبب من أسباب نمو سلوك المستهلك (ش15)."},{"i":3,"mis":"gen.neighbor","note":"نقطة من أهمية الدراسة لرجال الأعمال (ش10)."}],"tests":["الاتجاهات الحديثة في سلوك المستهلك","Brand Equity"]},{"n":201,"lo":"CH2","sec":"MKT231-CH2","type":"list","topic":"أنواع القرارات الشرائية","stem":"القرارات اللي يتخذها المستهلك تنقسم لأربعة أنواع رئيسية. وحدة من هذي مو منها:","options":["القرارات المتعلقة بتخصيص الموارد المتاحة له بين أوجه الانفاق المختلفة","القرارات المتعلقة بشراء علامة تجارية بعينها أو بطراز معين","القرارات المتعلقة بالتخلص من المنتج بعد استهلاكه","القرارات الخاصة باختيار المحلات التجارية"],"answer":2,"why":"الأنواع الأربعة في شرائح 6–7: تخصيص الموارد، شراء المنتجات من عدمه، علامة بعينها أو طراز معين، اختيار المحلات. التخلص من المنتج هو الخطوة السابعة من مراحل القرار (ش9)، مو نوع قرار.","wrong":[{"i":0,"mis":"gen.partial","note":"هذا النوع الأول (ش6)"},{"i":1,"mis":"gen.partial","note":"هذا النوع الثالث (ش7)"},{"i":3,"mis":"gen.partial","note":"هذا النوع الرابع (ش7)"}],"tests":["أنواع القرارات الشرائية"]},{"n":202,"lo":"CH2","sec":"MKT231-CH2","type":"figure","topic":"مراحل اتخاذ القرار الشرائي","stem":"حسب الشكل (2-1)، وش الخطوات اللي تقع تحت «مرحلة ما قبل الشراء»؟","img":"img/mkt231/CH2-s09.png","options":["الشعور بالمشكلة، البحث عن المعلومات، تقييم البدائل المتاحة","الشعور بالمشكلة، البحث عن المعلومات، تقييم البدائل المتاحة، اختيار البديل الأفضل","البحث عن المعلومات، تقييم البدائل المتاحة، اختيار البديل الأفضل، الشراء","الشعور بالمشكلة، البحث عن المعلومات، الشراء، تقييم المنتج أثناء الاستهلاك وبعده"],"answer":1,"why":"الشكل (2-1) ش9: ما قبل الشراء = 4 خطوات (1–4)، الشراء = الخطوة 5، وما بعد الشراء = الخطوتين 6 و7.","wrong":[{"i":0,"mis":"gen.partial","note":"ناقصة اختيار البديل الأفضل، وهو آخر خطوة قبل الشراء"},{"i":2,"mis":"k2.stage-step-placement","note":"الشراء مرحلة مستقلة، والشعور بالمشكلة هو البداية"},{"i":3,"mis":"k2.stage-step-placement","note":"تقييم المنتج أثناء الاستهلاك من مرحلة ما بعد الشراء"}],"tests":["مراحل اتخاذ القرار الشرائي","مرحلة ما قبل الشراء","الشكل 2-1"]},{"n":203,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"الشعور بالمشكلة الاستهلاكية","stem":"أحمد جواله شغال تمام وما هو زعلان منه، بس نزل في السوق جوال جديد بكاميرا سفر خرافية فصار يحس إنه يبيه قبل رحلته الجاية. شعوره بالمشكلة جاء من:","options":["تغير في الحالة الحالية: عدم رضا المستهلك عن المخزون الحالي من السلعة","تغير في الحالة الحالية: نضوب المخزون من السلعة لدى المستهلك","تغير في الحالة المرغوبة: الحاجة الى شراء المنتجات الأخرى المكملة","تغير في الحالة المرغوبة: ظهور منتجات جديدة في الأسواق"],"answer":3,"why":"ش11: «ظهور منتجات جديدة في الاسواق» من تغيرات الحالة المرغوبة. جواله ما تغير ولا هو زعلان منه، يعني الحالة الحالية ثابتة.","wrong":[{"i":0,"mis":"k2.current-vs-desired","note":"القصة تقول ما هو زعلان من جواله"},{"i":1,"mis":"k2.current-vs-desired","note":"جواله ما خلص ولا خرب"},{"i":2,"mis":"gen.neighbor","note":"المكمل شي يكمّل منتج عندك (زي حامل للكاميرا)، مو جهاز بديل جديد"}],"tests":["الشعور بالمشكلة الاستهلاكية","الحالة الحالية والحالة المرغوبة"]},{"n":204,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"مصادر المعلومات","stem":"قبل ما تشتري عائلة كرسي سيارة أطفال لرحلتهم البرية، قرأوا «مجلة المستهلك» اللي تصدرها هيئة المواصفات والمقاييس لدول مجلس التعاون. هذا المصدر:","options":["مصدر رسمي — المصادر الحكومية","مصدر رسمي — المصادر المستقلة","مصدر رسمي — المصادر التجارية","مصدر غير رسمي (شخصي)"],"answer":0,"why":"ش14 تذكر مجلة المستهلك من هيئة المواصفات والمقاييس لدول مجلس التعاون كمثال على المصادر الحكومية، وهي نوع من المصادر الرسمية (غير الشخصية).","wrong":[{"i":1,"mis":"k2.source-types","note":"مثال المستقلة اتحاد المستهلكين بالولايات المتحدة، وهي مو حكومية"},{"i":2,"mis":"k2.source-types","note":"التجارية مصدرها الشركة نفسها: إعلان، مندوب، عبوة"},{"i":3,"mis":"k2.source-types","note":"غير الرسمية = العائلة والأقارب والأصدقاء"}],"tests":["مصادر المعلومات","المصادر الرسمية","المصادر الحكومية","المصادر غير الرسمية"]},{"n":205,"lo":"CH2","sec":"MKT231-CH2","type":"term","topic":"معايير تقييم البدائل","stem":"المعايير اللي «تقود عملية الاختيار وتحسمها له لأنها الأكثر أهمية بالمقارنة بكل المعايير الأخرى من وجهه نظره» اسمها:","options":["معايير هامة Salient","معايير موضوعية","معايير حاسمة Determinant","معايير شخصية"],"answer":2,"why":"ش15: الحاسمة Determinant تجي في مقدمة المعايير الهامة، وهي اللي تقود الاختيار وتحسمه.","wrong":[{"i":0,"mis":"k2.salient-vs-determinant","note":"الهامة أوسع، والحاسمة هي رأسها"},{"i":1,"mis":"gen.neighbor","note":"الموضوعية تحددها الاختبارات المعملية زي قوة موتور السيارة"},{"i":3,"mis":"gen.neighbor","note":"الشخصية يحددها الحكم الشخصي زي صورة الطبقة الاجتماعية"}],"tests":["تقييم البدائل","المعايير الهامة","المعايير الحاسمة","المعايير الموضوعية والشخصية"]},{"n":206,"lo":"CH2","sec":"MKT231-CH2","type":"tf","topic":"تعميمات تقييم البدائل","stem":"كلما ازدادت الحاجة الى المنتج ماسة كان مجهود التقييم أكبر.","options":["صح","خطأ"],"answer":1,"why":"ش16 تقول العكس: كلما ازدادت الحاجة ماسة كان مجهود التقييم «أقل». اللي يزيد الجهد أهمية المنتج والمخاطرة المدركة، والبدائل المعقدة تطوّل التقييم.","wrong":[{"i":0,"mis":"k2.urgency-effort","note":"خلط الحاجة الماسة مع أهمية المنتج"}],"tests":["التعميمات المؤثرة في تقييم البدائل","المخاطرة المدركة"]},{"n":207,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"مجموعات العلامات التجارية","stem":"سارة جربت شركة طيران قبل، تأخرت رحلتها وضاعت شنطتها. من يومها تستبعد الشركة من حسابها وترفض تحجز عندها. الشركة هذي عند سارة في:","options":["المجموعة غير الفعالة Inert set","المجموعة المرفوضة Inept set","المجموعة المجهولة للمستهلك","المجموعة الحيوية Evoked set"],"answer":1,"why":"ش19: المرفوضة = علامات يستبعدها المستهلك ويرفض شراءها بسبب الآثار السيئة من تجربتها قبل أو بسبب نصائح الآخرين.","wrong":[{"i":0,"mis":"k2.inert-vs-inept","note":"غير الفعالة سببها نقص معلومات أو تصور إن مزاياها أقل، مو تجربة سيئة"},{"i":2,"mis":"gen.neighbor","note":"هي تعرف الشركة وجربتها، يعني معروفة"},{"i":3,"mis":"gen.reversed","note":"الحيوية هي اللي يتذكرها ويأخذها في اعتباره"}],"tests":["المجموعة المرفوضة","المجموعة غير الفعالة"]},{"n":208,"lo":"CH2","sec":"MKT231-CH2","type":"term","topic":"مجموعات العلامات التجارية","stem":"«العلامات التجارية التي لا يجد المستهلك في شرائها أية فائدة أو منفعة» بسبب عدم توفر المعلومات أو تصوره إن مزاياها أقل. هذي:","options":["المجموعة المرفوضة Inept set","المجموعة المستبعدة","المجموعة الحيوية Evoked set","المجموعة غير الفعالة Inert set"],"answer":3,"why":"ش19: هذا تعريف المجموعة غير الفعالة Inert set بالحرف. السبب فيها نقص معلومات أو إنه يشوف مزاياها أقل. لا تلخبطك كلمة «يستبعد هذه المجموعة» في آخر التعريف، الاسم الرسمي لها غير الفعالة.","wrong":[{"i":0,"mis":"k2.inert-vs-inept","note":"المرفوضة سببها تجربة سيئة قبل أو نصايح الناس، مو نقص معلومات"},{"i":1,"mis":"gen.neighbor","note":"المستبعدة فرع من الحيوية في الشكل (2-2)، مو هذا التعريف"},{"i":2,"mis":"gen.reversed","note":"الحيوية بالعكس، هي اللي يتذكرها وياخذها في اعتباره وقت التقييم"}],"tests":["المجموعة غير الفعالة","الشكل 2-2"]},{"n":209,"lo":"CH2","sec":"MKT231-CH2","type":"concept","topic":"المجموعة الحيوية","stem":"وش الصحيح عن المجموعة الحيوية Evoked set؟","options":["تسمى أيضاً المجموعة المأخوذة في الاعتبار، وغالباً تتراوح بين علامتين وخمس علامات","تضم كل العلامات التجارية الموجودة في السوق تحت نوع المنتج","تضم العلامات اللي يرفض المستهلك شراءها بسبب نصائح الآخرين","تسمى أيضاً المجموعة المأخوذة في الاعتبار، وغالباً تتراوح بين خمس وعشر علامات"],"answer":0,"why":"ش19: الحيوية = Consideration set، عدد صغير يتذكره المستهلك ويأخذه في اعتباره، «وغالباً ما تتراوح بين علامتين وخمس علامات».","wrong":[{"i":1,"mis":"gen.neighbor","note":"هذي المجموعة الكاملة Total set of Brands (ش17)"},{"i":2,"mis":"k2.inert-vs-inept","note":"هذي المرفوضة"},{"i":3,"mis":"gen.detail","note":"العدد غلط: من 2 إلى 5"}],"tests":["المجموعة الحيوية","المجموعة المأخوذة في الاعتبار","المجموعة الكاملة من العلامات"]},{"n":210,"lo":"CH2","sec":"MKT231-CH2","type":"figure","topic":"الشكل 2-2 مراحل اختيار العلامة","stem":"حسب الشكل (2-2) مراحل اختيار العلامة التجارية، «المجموعة المعروفة للمستهلك» تتفرع إلى:","img":"img/mkt231/CH2-s18.png","options":["مجموعة مستبقاه ومجموعة مستبعدة","مجموعة معروفة ومجموعة مجهولة","مجموعة حيوية ومجموعة مرفوضة ومجموعة غير فعالة","مجموعة حيوية ومجموعة مستبعدة ومجموعة مجهولة"],"answer":2,"why":"ش18: الكلية ← معروفة ومجهولة، والمعروفة ← حيوية ومرفوضة وغير فعالة، والحيوية ← مستبقاه ومستبعدة، ومن المستبقاه تطلع العلامة المختارة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا تفرع الحيوية، مستوى أنزل"},{"i":1,"mis":"gen.neighbor","note":"هذا تفرع المجموعة الكلية، مستوى أعلى"},{"i":3,"mis":"gen.partial","note":"خلط مستويات الشجرة ببعض"}],"tests":["الشكل 2-2","المجموعة المعروفة","المجموعة الحيوية","المجموعة المرفوضة"]},{"n":211,"lo":"CH2","sec":"MKT231-CH2","type":"list","topic":"جدول أساليب الاختيار","stem":"الأسلوب التعويضي وأسلوب الاختيار المرحلي يندرجون تحت:","options":["أساليب الاختيار في حالات الاهتمام القليل بالشراء","أساليب الاختيار التجريبي","أساليب الاختيار بين المحلات التجارية","أساليب الاختيار في حالات الاهتمام الكبير بالشراء"],"answer":3,"why":"جدول (2-4) ش22: الاهتمام الكبير = التعويضي والمرحلي. الاهتمام القليل = الشمولية والحذف والتكرار.","wrong":[{"i":0,"mis":"k2.involvement-groups","note":"المرحلي فيه أساليب شمولية جواه، بس هو نفسه تحت الاهتمام الكبير"},{"i":1,"mis":"gen.neighbor","note":"التجريبي = الولاء، الشعور العام، الاندفاعي"},{"i":2,"mis":"gen.neighbor","note":"المحلات مجموعة خامسة مستقلة"}],"tests":["جدول 2-4","أساليب الاختيار في حالات الاهتمام الكبير","مجموعات أساليب الاختيار الخمس"]},{"n":212,"lo":"CH2","sec":"MKT231-CH2","type":"figure","topic":"الأسلوب التعويضي","stem":"في الشكل (2-3) الأسلوب التعويضي، المستهلك اختار العلامة (ج) مع إن سعرها مرتفع. ليش؟","img":"img/mkt231/CH2-s25.png","options":["لأن جودتها فائقة وفيها خدمات بعد البيع ومساعدة كبيرة من رجال البيع، وهذي عوضته عن السعر المرتفع","لأنها استوفت الحد الأدنى في كل الخواص، وهذا يكفي للاختيار","لأنها الأرخص بين العلامات الثلاث","لأنه يحس نحوها بشعور إيجابي عام قوي بدون ما يقارن الخواص"],"answer":0,"why":"ش24–25: التعويضي = يختار البديل اللي صفاته الممتازة تعوضه عن صفات متدنية. (ج) جودتها فائقة وخدماتها ومساعدة رجال البيع كبيرة، وهذي عوضت السعر المرتفع.","wrong":[{"i":1,"mis":"k2.compensatory-vs-holistic","note":"هذا منطق القاعدة الاقترانية، وهي تحتاج أسلوب ثاني بعدها"},{"i":2,"mis":"gen.detail","note":"سعر (ج) مرتفع، الأرخص (أ)"},{"i":3,"mis":"k2.experiential-mixup","note":"هذا أسلوب الشعور الإيجابي العام (ش35)"}],"tests":["الأسلوب التعويضي","الشكل 2-3"]},{"n":213,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"القاعدة الاقترانية","stem":"خالد يدور فندق في العُلا. حط حد أدنى لكل خاصية: تقييم ما يقل عن 4، سعر ما يزيد عن 600 ريال، ومسافة ما تزيد عن 10 كم من المواقع الأثرية، واستبعد أي فندق ما يتوفر فيه الحد الأدنى من كل الخواص. هذي:","options":["القاعدة الخيارية Disjunctive Rule","القاعدة الاقترانية Conjunctive Rule","القاعدة المعجمية Lexicographic Rule","الأسلوب التعويضي"],"answer":1,"why":"ش26: الاقترانية = حد أدنى لكل خاصية، ويستبعد أي بديل ما يتوفر فيه الحد الأدنى من كل الخواص.","wrong":[{"i":0,"mis":"k2.conj-vs-disj","note":"الخيارية تقبل البديل لو حقق الحد الأدنى في أي خاصية بمفردها"},{"i":2,"mis":"k2.lexi-vs-elim","note":"المعجمية ترتب الخواص وتاخذ الأعلى في أهم خاصية، ما فيها حد أدنى لكل الخواص"},{"i":3,"mis":"k2.compensatory-vs-holistic","note":"في التعويضي الميزة تعوض العيب، وهنا أي خاصية تحت الحد تطلّع الفندق"}],"tests":["القاعدة الاقترانية","الأساليب الشمولية"]},{"n":214,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"القاعدة الخيارية","stem":"نورة حطت حد أدنى لكل خاصية تبيها في المنتجع (إطلالة بحرية، مسبح خاص، إفطار مجاني)، بس تقبل أي منتجع يتوفر فيه الحد الأدنى لأي خاصية بمفردها. هذي:","options":["القاعدة الاقترانية","أسلوب الحذف","القاعدة الخيارية","أسلوب التكرار"],"answer":2,"why":"ش28: الخيارية = حد أدنى لكل خاصية على حده، بس يقبل البديل اللي يتوفر فيه الحد الأدنى لأي خاصية بمفردها.","wrong":[{"i":0,"mis":"k2.conj-vs-disj","note":"الاقترانية تشترط الحد الأدنى في كل الخواص"},{"i":1,"mis":"k2.lexi-vs-elim","note":"الحذف يرتب الخواص ويشيل البدائل خاصية ورا خاصية لين يبقى واحد"},{"i":3,"mis":"gen.neighbor","note":"التكرار يعدّ الخواص الإيجابية والسلبية"}],"tests":["القاعدة الخيارية"]},{"n":215,"lo":"CH2","sec":"MKT231-CH2","type":"concept","topic":"المعجمي والحذف","stem":"الأسلوب المعجمي وأسلوب الحذف يبدأون نفس البداية: ترتيب الخواص حسب أهميتها ثم المقارنة على أهم خاصية. وين يختلفون؟","options":["المعجمي يُستخدم في حالات الاهتمام الكبير، والحذف في حالات الاهتمام القليل","المعجمي يحذف البدائل اللي ما تتمتع بحد أدنى من أهم خاصية، والحذف يختار البديل الأعلى فيها","المعجمي يختار البديل الأعلى مستوى في أهم خاصية، والحذف يشيل البدائل اللي ما تتمتع بحد أدنى منها وينتقل للخاصية الثانية لين يبقى بديل واحد","المعجمي يعتمد على عدد الخواص الإيجابية والسلبية، والحذف يعتمد على الشعور العام"],"answer":2,"why":"ش32: بعد أهم خاصية يختلفون: الحذف يحذف اللي ما فيه حد أدنى ويكمل لين يبقى واحد، والمعجمي يختار البديل اللي يتمتع بأعلى مستوى من الخاصية الأكثر أهمية.","wrong":[{"i":0,"mis":"k2.involvement-groups","note":"الاثنين تحت الاهتمام القليل في جدول (2-4)"},{"i":1,"mis":"k2.lexi-vs-elim","note":"عكست الاثنين"},{"i":3,"mis":"gen.neighbor","note":"هذا وصف أسلوب التكرار والشعور الإيجابي العام"}],"tests":["القاعدة المعجمية","أسلوب الحذف"]},{"n":216,"lo":"CH2","sec":"MKT231-CH2","type":"term","topic":"أسلوب التكرار","stem":"الأسلوب اللي عملية الاختيار فيه «تتأثر فقط بعدد الخواص الايجابية وعدد الخواص السلبية المرتبطة بالعلامة التجارية» هو:","options":["أسلوب الحذف Elimination by Aspect","أسلوب التكرار Frequency Heuristic","الاختيار طبقاً للشعور الإيجابي العام","القاعدة المعجمية"],"answer":1,"why":"ش33: هذا نص أسلوب التكرار، يعدّ الإيجابيات والسلبيات أو الجوانب اللي تتفوق فيها علامة على ثانية.","wrong":[{"i":0,"mis":"k2.lexi-vs-elim","note":"الحذف يشيل البدائل حسب الحد الأدنى لكل خاصية بالترتيب"},{"i":2,"mis":"k2.experiential-mixup","note":"الشعور العام ما يعد خواص أصلاً"},{"i":3,"mis":"gen.neighbor","note":"المعجمية تاخذ الأعلى في أهم خاصية"}],"tests":["أسلوب التكرار","أساليب الاختيار في حالات الاهتمام القليل"]},{"n":217,"lo":"CH2","sec":"MKT231-CH2","type":"term","topic":"الولاء للعلامة التجارية","stem":"«درجة الايجابية في الاتجاهات النفسية للعميل نحو تلك العلامة ومدى التزامه بشرائها في الوقت الحاضر وعزمه على الاستمرار في شرائها في المستقبل» هذا تعريف:","options":["رضا المستهلك","الولاء للمحل التجاري","الولاء للعلامة التجارية","الاختيار طبقاً للشعور الإيجابي العام"],"answer":2,"why":"ش34: تعريف الولاء للعلامة التجارية. ومديرو التسويق يسعون له لأن جلب عملاء جدد يكلف من 4 إلى 6 أضعاف الاحتفاظ بالحاليين.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الرضا = الأداء الفعلي يساوي التوقعات أو يتفوق عليها (ش46)"},{"i":1,"mis":"gen.keyword","note":"الولاء للمحل = ميل لارتياد أحد المتاجر باستمرار"},{"i":3,"mis":"k2.experiential-mixup","note":"الشعور العام اختيار حسب إحساس إيجابي قوي، بدون التزام مستقبلي"}],"tests":["الولاء للعلامة التجارية","أساليب الاختيار التجريبي"]},{"n":218,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"الشعور الإيجابي العام","stem":"فهد أول مرة يروح أبها. ما قارن أسعار ولا خدمات ولا أي خاصية، بس اختار المنتجع اللي يحس نحوه بشكل عام بشعور إيجابي قوي. هذا:","options":["الاختيار طبقاً للشعور الإيجابي العام Affect-Referral","الشراء في ظل الولاء للعلامة التجارية","الأسلوب التعويضي","أسلوب التكرار"],"answer":0,"why":"ش35: يختار البديل اللي يشعر نحوه بصفة عامة بشعور إيجابي وقوي، وما يقارن على أساس الخواص. زي الشكل (2-7) اللي اختار فيه (ب) لأن شعوره نحوها إيجابي قوي.","wrong":[{"i":1,"mis":"k2.experiential-mixup","note":"الولاء يحتاج شراء سابق والتزام يستمر، وهو أول مرة"},{"i":2,"mis":"k2.compensatory-vs-holistic","note":"التعويضي يقارن خواص ويعوض بعضها ببعض"},{"i":3,"mis":"gen.neighbor","note":"التكرار يعد الخواص الإيجابية والسلبية"}],"tests":["الاختيار طبقاً للشعور الإيجابي العام","الشكل 2-7"]},{"n":219,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"الشراء الاندفاعي","stem":"وهي تنتظر رحلتها في المطار، شافت مها عند الكاشير عرض «القطعة الثانية مجاناً» على ميداليات تذكارية صغيرة، وأخذتها فوراً بدون أي تخطيط. هذا:","options":["أسلوب الحل الروتيني","الاختيار طبقاً للشعور الإيجابي العام","أسلوب الحل متوسط المدى","الشراء الاندفاعي Impulse buying"],"answer":3,"why":"ش38: الشراء الاندفاعي = شراء عفوي غير مخطط له يتم في التو واللحظة بسبب أساليب العرض أو وسائل تنشيط المبيعات عند نقطة البيع. والمنتج رخيص وصغير وخفيف (ش39).","wrong":[{"i":0,"mis":"k2.solving-styles","note":"الروتيني شراء متكرر لنفس المنتج زي الخبز والحليب، مو شراء مفاجئ"},{"i":1,"mis":"k2.experiential-mixup","note":"الشعور العام مقارنة بين بدائل حسب الإعجاب الكلي، مو رغبة مفاجئة بسبب عرض"},{"i":2,"mis":"k2.solving-styles","note":"متوسط المدى لمنتجات متوسطة الثمن فيها بحث معقول"}],"tests":["الشراء الاندفاعي","خصائص الشراء الاندفاعي","العوامل المتعلقة بالمنتجات والنشاط التسويقي"]},{"n":220,"lo":"CH2","sec":"MKT231-CH2","type":"tf","topic":"عوامل الشراء الاندفاعي","stem":"يوجد دليل علمي على علاقة قوية بين شخصية المستهلك وخصائصه الديموغرافية أو الاجتماعية أو الاقتصادية وبين نزعته للشراء الاندفاعي.","options":["صح","خطأ"],"answer":1,"why":"ش39: «ليس هناك دليل علمي» على هالعلاقة. العوامل اللي ذكرتها البحوث هي المتعلقة بالمنتجات والمتعلقة بالنشاط التسويقي.","wrong":[{"i":0,"mis":"gen.reversed","note":"الشريحة تنفي وجود الدليل"}],"tests":["عوامل الشراء الاندفاعي","العوامل المتعلقة بالمستهلكين"]},{"n":221,"lo":"CH2","sec":"MKT231-CH2","type":"concept","topic":"المنتجات غير البديلة","stem":"لما يختار المستهلك بين أنواع منتجات غير بديلة (زي كاميرا أو جهاز تسجيل أو جهاز فيديو أو تليفزيون)، ليش الأساليب الشمولية (غير التعويضية) ما تساعده؟","options":["لأنها تتطلب رأيه في مجموعة من الخواص المشتركة، وهذي المنتجات ما بينها خواص مشتركة غير السعر","لأن هذي المنتجات رخيصة ومتكررة الشراء","لأن المستهلك يشتريها دايماً بدافع الولاء للعلامة","لأن الأساليب الشمولية تُستخدم بس في اختيار المحلات التجارية"],"answer":0,"why":"ش41: الشمولية تحتاج خواص مشتركة، وهذي المنتجات ما يجمعها إلا السعر. فالأفراد يا يستخدمون خواص تجريبية (ضرورة الحاجة، التصميم، الذوق العام، التكلفة، الابتكارية) يا تقييم كلي شامل حسب اتجاهاتهم النفسية.","wrong":[{"i":1,"mis":"gen.detail","note":"الأجهزة الكهربائية والإلكترونية مو منتجات ميسرة رخيصة"},{"i":2,"mis":"k2.experiential-mixup","note":"الشريحة ما ربطتها بالولاء"},{"i":3,"mis":"gen.absolute","note":"الشمولية من أساليب الاهتمام القليل، مو خاصة بالمحلات"}],"tests":["أساليب الاختيار بين المنتجات غير البديلة","الخواص التجريبية"]},{"n":222,"lo":"CH2","sec":"MKT231-CH2","type":"term","topic":"الولاء للمحل التجاري","stem":"«ميل المستهلك، لارتياد احد المتاجر بصورة مستمرة» هذا تعريف:","options":["الولاء للعلامة التجارية","الولاء للمحل التجاري Store Loyalty","أسلوب الحل الروتيني","اختيار المحلات التجارية Store selection"],"answer":1,"why":"ش43: تعريف الولاء للمحل التجاري، وممكن يكون أحياناً أقوى من الولاء لعلامة معينة.","wrong":[{"i":0,"mis":"gen.keyword","note":"الولاء للعلامة عن ماركة، مو متجر"},{"i":2,"mis":"k2.solving-styles","note":"الروتيني أسلوب حل للمشكلة (خبز، حليب)"},{"i":3,"mis":"gen.neighbor","note":"Store selection تقييم المحلات بالمعايير والمقارنة بينها، مو الميل المستمر"}],"tests":["الولاء للمحل التجاري","اختيار المحلات التجارية","معايير اختيار المحل"]},{"n":223,"lo":"CH2","sec":"MKT231-CH2","type":"tf","topic":"رضا المستهلك","stem":"يتحقق الرضا لما يكون الأداء الفعلي للمنتج أكبر من أو يساوي توقعات المستهلك عنه.","options":["صح","خطأ"],"answer":0,"why":"ش45: «يتحقق الرضاء عندما يكون الأداء الفعلي للمنتج أكبر من او يساوي توقعات المستهلك عنه»، وعدم الرضا لما يكون الأداء أقل.","wrong":[{"i":1,"mis":"k2.satisfaction-equal","note":"المساواة لحالها تكفي للرضا"}],"tests":["رضا المستهلك","عدم رضا المستهلك"]},{"n":224,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"الصراع النفسي بعد الشراء","stem":"سلمان دفع حق رحلة بحرية، وبعدها قرأ تقييمات متضاربة عنها وصار قلقان، فراح يدور الإعلانات اللي تمدح الرحلة ويتجنب إعلانات الشركات المنافسة. اللي صار له:","options":["عدم رضاء المستهلك Consumer dissatisfaction","الشعور بالمشكلة الاستهلاكية","الصراع النفسي بعد الشراء Post-Purchase Dissonance","الشراء الاندفاعي"],"answer":2,"why":"ش48: الصراع النفسي بعد الشراء = عدم توازن نفسي من معلومات متضاربة بعد قرار الشراء. والبحث عن إعلانات داعمة مع تجنب المنافسة وحدة من وسائل تخفيضه (ش49).","wrong":[{"i":0,"mis":"k2.dissonance-vs-dissatisfaction","note":"عدم الرضا يجي بعد الاستهلاك لما الأداء أقل من التوقعات، وهو لسا ما جرب الرحلة"},{"i":1,"mis":"k2.stage-step-placement","note":"الشعور بالمشكلة بداية القرار، قبل الشراء"},{"i":3,"mis":"gen.neighbor","note":"ما فيه شراء مفاجئ غير مخطط هنا"}],"tests":["الصراع النفسي بعد الشراء","وسائل تخفيض الصراع النفسي"]},{"n":225,"lo":"CH2","sec":"MKT231-CH2","type":"list","topic":"طرق التعبير عن عدم الرضا","stem":"من «الإجراءات الرسمية» للتعبير عن عدم الرضا:","options":["رفع الأمر الى القضاء","مقاطعة الشركة البائعة","الشكوى لمدير متجر التجزئة","إنشاء تنظيم بديل لإمداد المستهلكين مثل الجمعيات التعاونية"],"answer":0,"why":"ش47: الإجراءات الرسمية 3: تقديم شكوى للجهة الرسمية المختصة، كتابة خطاب لإحدى الصحف المحلية، رفع الأمر الى القضاء. الباقي طرق مستقلة من الطرق الست.","wrong":[{"i":1,"mis":"gen.partial","note":"المقاطعة طريقة مستقلة (الرابعة)"},{"i":2,"mis":"gen.keyword","note":"الشكوى للمدير الطريقة الأولى، مو إجراء رسمي"},{"i":3,"mis":"gen.partial","note":"التنظيم البديل الطريقة الخامسة"}],"tests":["طرق التعبير عن عدم الرضا","الإجراءات الرسمية"]},{"n":226,"lo":"CH2","sec":"MKT231-CH2","type":"figure","topic":"التخلص من المنتج","stem":"حسب الشكل (2-8) طرق التخلص من المنتج بعد الاستهلاك، «استخدامه في غرض جديد» يقع تحت:","img":"img/mkt231/CH2-s52.png","options":["التخلص منه نهائياً — بيعه","الاحتفاظ بالمنتج","فرع تأجيره أو إقراضه","التخلص منه نهائياً — اهداؤه لآخر"],"answer":1,"why":"ش52: الاحتفاظ بالمنتج له 3 طرق: استخدامه في غرضه الأصلي، استخدامه في غرض جديد، تخزينه.","wrong":[{"i":0,"mis":"gen.neighbor","note":"البيع: مباشرة للمستهلك، من خلال الوسطاء، للوسطاء"},{"i":2,"mis":"gen.neighbor","note":"التأجير والإقراض فرع ثالث مستقل"},{"i":3,"mis":"gen.neighbor","note":"الإهداء: اللي ياخذه يستخدمه أو يعيد بيعه"}],"tests":["التخلص من المنتج","الشكل 2-8"]},{"n":227,"lo":"CH2","sec":"MKT231-CH2","type":"scenario","topic":"أساليب حل المشكلة الاستهلاكية","stem":"سائح يحجز فندق متوسط السعر لرحلة عمل. حاجته للمعلومات مو كبيرة، ويجيبها بسهولة من مصادر قريبة، والفنادق مزاياها متنوعة بس متشابهة لحد كبير، والمخاطرة مو كبيرة. الأسلوب المناسب:","options":["أسلوب الحل المسهب Extended","أسلوب الحل الروتيني Routinized","أسلوب الحل متوسط المدى Midrange","أسلوب الحل المحدود Limited"],"answer":2,"why":"ش57: هذي حالات متوسط المدى الأربع نفسها، و«الخدمات الفندقية» من أمثلته الصريحة.","wrong":[{"i":0,"mis":"k2.solving-styles","note":"المسهب: أول مرة، مزايا فريدة، ثمن مرتفع، أهمية بالغة"},{"i":1,"mis":"k2.solving-styles","note":"الروتيني ما يبحث عن معلومات أصلاً"},{"i":3,"mis":"k2.solving-styles","note":"المحدود: مخاطرة منخفضة، بدائل كثيرة متشابهة، معلومات قليلة، منتجات ميسرة"}],"tests":["أسلوب الحل متوسط المدى","أسلوب الحل المسهب","أساليب حل المشكلة الاستهلاكية"]},{"n":228,"lo":"CH2","sec":"MKT231-CH2","type":"tf","topic":"أسلوب الحل المحدود","stem":"أسلوب الحل المحدود هو أكثر الأساليب استخداماً في معظم المواقف الشرائية اللي يمر بها الأفراد والعائلات.","options":["صح","خطأ"],"answer":0,"why":"ش58 بالنص: المحدود «اكثر الاساليب استخداماً في معظم المواقف الشرائية». ومن سماته إن الشراء الاندفاعي أقل أنواعه تعقيداً (ش59).","wrong":[{"i":1,"mis":"k2.solving-styles","note":"يحسب الروتيني هو الأكثر استخداماً"}],"tests":["أسلوب الحل المحدود","أسلوب الحل الروتيني","أساليب حل المشكلة الاستهلاكية"]},{"n":401,"lo":"CH4","sec":"MKT231-CH4","type":"term","topic":"تعريف الموقع التنافسي","stem":"أي ربط صحيح بين المصطلح وتعريفه حسب الشرائح؟","options":["الصورة الذهنية ← «الصورة أو الفكرة التي تتكون في أذهان المستهلكين عن المنتج بالمقارنة بالمنتجات أو العلامات التجارية الأخرى المنافسة»","الموقع التنافسي الفعال ← «التقييم الشخصي للمستهلك للمزايا والفوائد والمنافع التي يتصور حصوله عليها من جراء استعمالها»","الموقع التنافسي للمنتج ← «الصورة أو الفكرة التي تتكون في أذهان المستهلكين عن المنتج بالمقارنة بالمنتجات أو العلامات التجارية الأخرى المنافسة»","الموقع التنافسي للمنتج ← «الموقع الذي ينجح في إقناع المستهلكين باتصاف العلامة التجارية بميزة فريدة او بصفة معينة وبتفوقها»"],"answer":2,"why":"شريحة 6: «يعبر الموقع التنافسي للمنتج عن الصورة أو الفكرة التي تتكون في أذهان المستهلكين عن المنتج بالمقارنة...». المفتاح «بالمقارنة». أما «التقييم الشخصي...» فهو تعريف الصورة الذهنية (ش9)، و«الموقع الذي ينجح في إقناع المستهلكين...» تعريف الموقع الفعال (ش12).","wrong":[{"i":0,"mis":"k4.position-vs-image","note":"هذا تعريف الموقع مو الصورة؛ الصورة الذهنية = «التقييم الشخصي للمستهلك...» (ش9)."},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف الصورة الذهنية (ش9)، مو الموقع الفعال."},{"i":3,"mis":"gen.partial","note":"هذا تعريف الموقع التنافسي «الفعال» تحديداً (ش12)، مو الموقع العام."}],"tests":["الموقع التنافسي للمنتج","الصورة الذهنية للمنتج أو العلامة","الموقع التنافسي الفعال"]},{"n":402,"lo":"CH4","sec":"MKT231-CH4","type":"tf","topic":"إعادة تصميم الموقع","stem":"إعادة تصميم الموقع التنافسي (Product Repositioning) يعني إن الشركة تنقل المنتج لقطاع سوقي جديد، ولازم تغيّر كل خصائص العلامة.","options":["صح","خطأ"],"answer":1,"why":"خطأ. شريحة 8: إعادة التصميم تكون «لنفس القطاع السوقي دون تغيير خصائص العلامة أو ربما مع تحسين أو تغيير احداها»، وسببها «الظروف البيئية المتغيرة».","wrong":[{"i":0,"mis":"k4.repositioning-scope","note":"لا قطاع جديد ولا تغيير كل الخصائص؛ نفس القطاع، وبالكثير تحسين أو تغيير خاصية وحدة."}],"tests":["إعادة تصميم الموقع التنافسي (Product Repositioning)"]},{"n":403,"lo":"CH4","sec":"MKT231-CH4","type":"list","topic":"عوامل نجاح المزيج التسويقي","stem":"حسب الشرائح، نجاح المزيج التسويقي للمنشأة يعتمد على عاملين أساسيين. وش هم؟","options":["وجود استراتيجية فعالة لتجزئة السوق، وتصميم موقع تنافسي مناسب للمنتج","إعداد الخريطة الإدراكية، وتحليل المنافسة وتحديد المنافسين","تحديد الخصائص الحاسمة للمنتج، ومتابعة الموقع التنافسي المختار","قياس الصورة الذهنية من وقت لآخر، وإعادة تصميم الموقع التنافسي"],"answer":0,"why":"شريحة 6: «يعتمد نجاح المزيج التسويقي للمنشأة على عاملين اساسيين هما: وجود استراتيجية فعالة لتجزئة السوق، تصميم موقع تنافسي مناسب للمنتج». وعشان كذا الفصل جاي في قسم «تجزئة السوق واستهداف قطاعاته».","wrong":[{"i":1,"mis":"gen.neighbor","note":"هذي أدوات وخطوات داخل تصميم الموقع (ش30، 33)، مو عاملين نجاح المزيج."},{"i":2,"mis":"k4.steps-order","note":"هذي الخطوة الرابعة والسادسة من خطوات التصميم (ش31–32)."},{"i":3,"mis":"gen.neighbor","note":"القياس وإعادة التصميم أشياء يحتاجها مسؤول التسويق (ش8)، مو العاملين."}],"tests":["عوامل نجاح المزيج التسويقي"]},{"n":404,"lo":"CH4","sec":"MKT231-CH4","type":"tf","topic":"الصورة الفعلية مقابل الموقع المستهدف","stem":"الصورة الذهنية الفعلية عند المستهلكين ممكن تطابق الموقع التنافسي اللي يستهدفه مدير التسويق أو تختلف عنه، بسبب عوامل منها خبرة المستهلك وتجاربه السابقة وإدراكه الحسي والجهود التسويقية للمنافسين.","options":["صح","خطأ"],"answer":0,"why":"صح. شريحة 7: الصورة الفعلية «قد تطابق الموقع التنافسي الذي يستهدفه مدير التسويق او تختلف عنه» بسبب عوامل منها: الخبرة والتجارب السابقة، الإدراك الحسي، القدرة على التعلم، الاتجاهات النفسية والميول، توفر المعلومات عن المنافسين، وجهود المنافسين التسويقية.","wrong":[{"i":1,"mis":"k4.position-vs-image","note":"اللي يقول خطأ يحسب إن اللي تصممه الشركة يطلع نفسه بالضبط في راس المستهلك؛ لا، ممكن يختلف."}],"tests":["عوامل اختلاف الصورة الذهنية عن الموقع المستهدف"]},{"n":405,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"أهمية الموقع المميز","stem":"شركة سياحة لاحظت إن ولا منافس يقدّم رحلات مهيأة لكبار السن (مرافق صحي، برنامج هادي)، فصممت لهم مزيج تسويقي كامل بموقع تنافسي قوي. هذا يوضح أي سبب من أسباب أهمية تحديد موقع تنافسي مميز؟","options":["تزايد عدد المنتجات البديلة اللي تشبع نفس الحاجة مع إحساس المستهلك بعدم وجود فروق جوهرية بينها","الحاجة لإعادة تصميم الموقع التنافسي عند وصول المنتج لمرحلة النضج في دورة حياته","تزايد احتمالات فشل استراتيجية تجزئة السوق بدون موقع مميز لكل قطاع","استغلال الثغرات الموجودة في السوق (Market Niches) اللي غفل عنها المنافسون"],"answer":3,"why":"شريحة 11: «استغلال الثغرات الموجودة في السوق ( Market Niches)، والتي غفل عنها المنافسون، فتقوم الشركة بإشباع الحاجات المتعلقة بهذه الثغرات بمزيج تسويقي فعال يعبر عنه موقع تنافسي قوي». المفتاح: «ولا منافس يقدّم» = ثغرة غفل عنها المنافسون.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا سبب عن كثرة البدائل المتشابهة (ش10)، والقصة هنا عن حاجة ما أحد غطاها."},{"i":1,"mis":"k4.repositioning-scope","note":"النضج يخص منتج قديم مبيعاته ثابتة أو تنقص (ش11)، مو خدمة جديدة."},{"i":2,"mis":"gen.neighbor","note":"هذا عن تجزئة بدون موقع لكل قطاع (ش10)، مو عن ثغرة في السوق."}],"tests":["أسباب أهمية الموقع المميز الخمسة","Market Niches"]},{"n":406,"lo":"CH4","sec":"MKT231-CH4","type":"tf","topic":"قواعد نابلر","stem":"وضع نابلر ثلاث قواعد إدراكية هامة وضرورية لنجاح الموقع التنافسي للمنتج.","options":["صح","خطأ"],"answer":1,"why":"خطأ. شريحة 12: «وضع نابلر أربع قواعد إدراكية»: (١) تعريف وتحديد السوق المستهدفة بدقة (٢) المستهلك يشتري المنافع مو الخصائص الفنية، فترجم الخصائص لمنافع (٣) الميزة اللي ما يعتبرها المستخدم مهمة نصرف النظر عنها (٤) إذا ما صدّق المستهلك إن المنتج يوفر الميزة فلا فايدة من الموقع. الرقم ٣ هو عدد «الشروط» في ش13.","wrong":[{"i":0,"mis":"k4.list-counts","note":"٣ عدد شروط الموقع الفعال (ش13)؛ قواعد نابلر ٤."}],"tests":["قواعد نابلر الأربع"]},{"n":407,"lo":"CH4","sec":"MKT231-CH4","type":"list","topic":"شروط الموقع الفعال","stem":"أي واحد من التالي من الشروط اللي لازم تتوفر في الموقع التنافسي الفعال للمنتج (شريحة 13)؟","options":["التركيز على الخصائص الفنية والتقنية للمنتج بدل منافعه","توافق الموقع التنافسي مع السوق المستهدف","تصميم الموقع التنافسي بحيث يناسب كل الناس","التركيز على أي ميزة تقدر الشركة تبرزها حتى لو المستهلك ما يعتبرها مهمة"],"answer":1,"why":"شريحة 13: الشروط ٣: (١) توافق الموقع التنافسي مع السوق المستهدف (٢) القدرة على إقناع السوق المستهدف بمحتوى الموقع (٣) التركيز على المنفعة ذات الأهمية من وجهة نظر المستهلك.","wrong":[{"i":0,"mis":"k4.features-not-benefits","note":"نابلر قال المستهلك ما يشتري الخصائص الفنية، يشتري المنافع (ش12)."},{"i":2,"mis":"k4.weak-looks-good","note":"«تصميم الموقع التنافسي بحيث يناسب كل الناس» من أسباب الضعف (ش15)."},{"i":3,"mis":"gen.reversed","note":"الشرط الثالث يقول العكس: نصرف النظر عن الميزة اللي ما يعتبرها المستهلك مهمة."}],"tests":["شروط الموقع التنافسي الفعال الثلاثة"]},{"n":408,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"خصائص الفرق","stem":"شركة طيران صارت أول وحدة تقدّم خدمة «مندوب يجيك البيت ويخلّص إجراءات سفرك وشحن عفشك»، ولا منافس قدّمها قبلها. حسب خصائص الفرق اللي يقوم عليه الموقع التنافسي (شريحة 14)، هذا الفرق يحقق بالدرجة الأولى خاصية:","options":["أن يكون متميزاً","أن يكون مربحاً","أن يكون فريداً","أن تكون التكاليف المترتبة عليه مقبولة"],"answer":2,"why":"شريحة 14: «أن يكون فريداً: لم يقدمه أحد المنافسين من قبل أو أن تقدمه الشركة للمستهلكين بطريقة جديدة». المفتاح «ولا منافس قدّمها قبلها».","wrong":[{"i":0,"mis":"k4.unique-vs-distinct","note":"متميز = يمتاز على كل طرق المنافسين في تحقيق منفعة أفضل؛ القصة تركز على إنه أول مرة، وهذا تعريف فريد."},{"i":1,"mis":"gen.neighbor","note":"مربح = الشركة تحقق ربح من وراه؛ القصة ما ذكرت ربح."},{"i":3,"mis":"gen.neighbor","note":"التكاليف المقبولة = المشتري يقدر يتحمل ثمن الفرق؛ ما لها علاقة بإنه جديد."}],"tests":["خصائص الفرق السبع","فريد مقابل متميز"]},{"n":409,"lo":"CH4","sec":"MKT231-CH4","type":"list","topic":"أسباب المواقع الضعيفة","stem":"أي واحد من التالي من أسباب المواقع التنافسية الضعيفة للمنتج (شريحة 15)؟","options":["توافق الموقع التنافسي مع السوق المستهدف","تشويش الموقع التنافسي بسبب التوسع في خط المنتجات","استغلال الثغرات الموجودة في السوق (Market Niches)","التركيز على المنفعة ذات الأهمية من وجهة نظر المستهلك"],"answer":1,"why":"شريحة 15 فيها ١٢ سبب، منها «تشويش الموقع التنافسي بسبب التوسع في خط المنتجات». الخيار الأول والرابع من شروط الموقع الفعال (ش13)، والثالث من أسباب أهمية الموقع (ش11).","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا شرط من شروط الموقع الفعال (ش13)، مو سبب ضعف."},{"i":2,"mis":"gen.neighbor","note":"استغلال الثغرات سبب من أسباب أهمية الموقع المميز (ش11)."},{"i":3,"mis":"gen.reversed","note":"هذا شرط فعال؛ سبب الضعف هو عكسه: «التركيز على خاصية غير هامة للمستهلك»."}],"tests":["أسباب المواقع التنافسية الضعيفة الاثنا عشر"]},{"n":410,"lo":"CH4","sec":"MKT231-CH4","type":"figure","topic":"الشكل (٤-١) الاستراتيجيات","stem":"في الشكل (٤-١) «استراتيجيات الموقع التنافسي للمنتج»، الصندوق المكتوب فيه «جماعة المستهلكين» يقابل أي استراتيجية؟","img":"img/mkt231/CH4-s18.png","options":["Positioning by Psychological needs","Positioning by cultural values / Symbols","Positioning by use or application","Positioning by product user"],"answer":3,"why":"شريحة 16: «تحديد الموقع التنافسي طبقاً لجماعة العملاء ( مستعملي السلعة) Positioning by product user»، وفي الشكل (ش18) صندوقها اسمه «جماعة المستهلكين». الحاجات النفسية صندوقها «الحاجات النفسية»، والقيم الحضارية صندوقها «التراث الثقافي»، وطريقة الاستعمال صندوقها «طريقة الاستعمال».","wrong":[{"i":0,"mis":"k4.user-vs-psych","note":"الحاجات النفسية لها صندوق لحالها في الشكل؛ الاثنين فيهم طبقة عليا بس مو نفس الاستراتيجية."},{"i":1,"mis":"gen.neighbor","note":"القيم والرموز الحضارية صندوقها «التراث الثقافي»."},{"i":2,"mis":"gen.neighbor","note":"طريقة الاستعمال صندوقها «طريقة الاستعمال»."}],"tests":["الاستراتيجيات الثمانية","الشكل (٤-١)","Positioning by product user"]},{"n":411,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"طرق تمييز المنتج","stem":"فندق يركّز في إعلاناته على إن موظفين الاستقبال عنده أكفاء ويستجيبون لطلبات النزلاء بسرعة. حسب الطرق الأربع لتمييز المنتج أو العلامة (شريحة 19)، هذا تمييز باستخدام مزايا خاصة بـ:","options":["العاملين بالشركة","المنتج نفسه مثل الجودة أو الأداء والتصميم","الخدمات المرتبطة بالمنتج مثل التسليم السريع والصيانة","الشركة المنتجة مثل تمتعها بتقنية متقدمة في التصنيع"],"answer":0,"why":"شريحة 19: الطريقة الرابعة «استخدام مزايا خاصة بالعاملين بالشركة كالكفاءة في الأداء والاستجابة السريعة للعملاء». والطرق الأربع: المنتج نفسه · الخدمات المرتبطة · الشركة المنتجة · العاملين.","wrong":[{"i":1,"mis":"gen.neighbor","note":"المنتج نفسه = الجودة أو الأداء والتصميم، والقصة عن الموظفين."},{"i":2,"mis":"gen.keyword","note":"كلمة «سريع» تلخبط: «التسليم السريع» خدمة مرتبطة بالمنتج، بس «الاستجابة السريعة للعملاء» ميزة للعاملين."},{"i":3,"mis":"gen.neighbor","note":"الشركة المنتجة = تقنية متقدمة في التصنيع، مو كفاءة الموظفين."}],"tests":["طرق تمييز المنتج الأربع","Positioning by Attribute"]},{"n":412,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"فرق واحد أم فروق متعددة","stem":"فندقين في نفس المدينة كل واحد يدّعي إنه «الأفضل في النظافة». حسب وجهة نظر مؤيدي الفروق المتعددة (شريحة 21)، وش المفروض يسوي الفندق الأول؟","options":["يركز على النظافة بس، لأن المستهلك يتذكر الرسائل اللي تركز على المركز الأول","يقلّد موقع الفندق الثاني عشان ما يخسر عملاءه","يشير لأكثر من فرق أو ميزة عشان يتمتع بميزة نسبية ثانية تميزه عن المنافس","يصمم موقعه بحيث يناسب كل الناس"],"answer":2,"why":"شريحة 21: لما «شركتان او أكثر» تدعي إنها الأفضل في ميزة معينة «يجب على الشركة المعنية الاشارة الى اكثر من فرق أو أكثر من ميزة ... حتى تتمتع بميزة نسبية أخرى تميزها عن المنافسين». مثالها ألبان نادك: الطعم والجودة.","wrong":[{"i":0,"mis":"k4.single-vs-multiple","note":"هذا رأي مؤيدي الفرق الواحد (مياه بركة، ش20)، والسؤال عن الفروق المتعددة."},{"i":1,"mis":"k4.weak-looks-good","note":"«تقليد أحد مواقع العلامات المنافسة تقليداً أعمى» سبب ضعف (ش15)."},{"i":3,"mis":"k4.weak-looks-good","note":"«تصميم الموقع التنافسي بحيث يناسب كل الناس» سبب ضعف (ش15)."}],"tests":["الفرق الواحد مقابل الفروق المتعددة","مثال نادك ومثال بركة"]},{"n":413,"lo":"CH4","sec":"MKT231-CH4","type":"concept","topic":"السعر والجودة","stem":"في استراتيجية تحديد الموقع طبقاً للعلاقة بين السعر والجودة (شريحة 22)، العلاقة تأخذ أحد اتجاهين. وش هم؟","options":["السعر المرتفع بجودة منخفضة، والسعر المنخفض بجودة مرتفعة","السعر المرتفع بجودة مرتفعة، والسعر المنخفض المرتبط بقيمة كبيرة","السعر المرتفع بجودة مرتفعة بس، لأن العلاقة دايماً طردية","السعر المنخفض بجودة منخفضة، والسعر المرتفع المرتبط بقيمة كبيرة"],"answer":1,"why":"شريحة 22: (١) «السعر المرتفع بجودة مرتفعة»، لأن كثير من المستهلكين يؤمنون بعلاقة طردية بين السعر والجودة، ومثالها سيارات لكزس في خطوط تويوتا (٢) «السعر المنخفض المرتبط بقيمة كبيرة».","wrong":[{"i":0,"mis":"gen.reversed","note":"معكوس؛ ما فيه سعر عالي بجودة منخفضة في الشريحة."},{"i":2,"mis":"k4.price-quality-one-way","note":"فيه اتجاه ثاني: السعر المنخفض المرتبط بقيمة كبيرة."},{"i":3,"mis":"gen.reversed","note":"القيمة الكبيرة مرتبطة بالسعر المنخفض مو المرتفع."}],"tests":["Positioning by price/quality","اتجاها السعر والجودة"]},{"n":414,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"فئة المنتج","stem":"شركة قهوة سريعة الذوبان تقول في إعلانها: «جاهزة في ثواني، مو زي القهوة العربية التقليدية اللي تاخذ وقت طويل في التحضير». هذي أي استراتيجية؟","options":["تحديد الموقع التنافسي بالمقارنة المباشرة مع المنافسين","تحديد الموقع التنافسي طبقاً لطريقة استعمال المنتج","تحديد الموقع التنافسي طبقاً للعلاقة بين السعر والجودة","تحديد الموقع التنافسي طبقاً لنوع أو فئة المنتج (Product class)"],"answer":3,"why":"هذا مثال شريحة 25 بالضبط: الشركة المنتجة للقهوة سريعة الذوبان تحدد موقعها «من حيث السرعة في التحضير بالمقارنة بالقهوة العربية التقليدية»، يعني تستغل «نوع وطبيعة المنتج نفسه». المقارنة هنا مع نوع منتج، مو مع علامة منافسة محددة.","wrong":[{"i":0,"mis":"gen.keyword","note":"كلمة «مقارنة» تخدع؛ المقارنة المباشرة تكون مع «العلامات المنافسة كلها أو مع واحدة بالتحديد» (ش28)، وهنا المقارنة مع فئة منتج."},{"i":1,"mis":"k4.class-vs-use","note":"طريقة الاستعمال = اقتراح طرق جديدة لاستعمال المنتج (معلبات في كل الوجبات، ش23)."},{"i":2,"mis":"gen.neighbor","note":"ما فيه أي ذكر للسعر أو الجودة."}],"tests":["Positioning by product class/type","فئة المنتج مقابل المقارنة بالمنافسين"]},{"n":415,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"الحاجات النفسية","stem":"إعلان لدرجة الأعمال في شركة طيران يقول: «رحلتك لازم تعكس ثقتك بنفسك وطموحك.. لأنك تستاهل الفخامة». هذا الإعلان يطبق أي استراتيجية؟","options":["تحديد الموقع التنافسي طبقاً لجماعة المستهلكين (Positioning by product user)","تحديد الموقع التنافسي طبقاً للحاجات النفسية للمستهلكين (Positioning by Psychological needs)","تصميم الموقع التنافسي باستخدام القيم والرموز الحضارية","تحديد الموقع التنافسي طبقاً لطريقة استعمال المنتج"],"answer":1,"why":"شريحة 27: الموقع يتصمم «تبعاً لدوافع الشراء لدى المستهلكين، أو بما يتفق مع حاجاتهم النفسية كالحاجة الى تقدير الذات والحاجة الى تحقيق الذات»، والإعلانات «تخاطب أسلوبهم المعيشي في الفخامة والتميز وتعكس طموحهم». زي عطر مسيو كازانوفا «الثقة بالنفس» وBMW «مكانك في احضان الفخامة».","wrong":[{"i":0,"mis":"k4.user-vs-psych","note":"جماعة المستهلكين تربط العلامة بفئة عملاء أو طبقة (مجوهرات للطبقة العليا، ش24)؛ هنا الإعلان يخاطب حاجة نفسية (ثقة بالنفس وطموح)."},{"i":2,"mis":"gen.neighbor","note":"القيم الحضارية = قيم دينية أو عادات وتقاليد (وجبات حلال)، مو ثقة بالنفس."},{"i":3,"mis":"gen.neighbor","note":"ما فيه اقتراح طريقة استعمال جديدة."}],"tests":["Positioning by Psychological needs","جماعة المستهلكين مقابل الحاجات النفسية"]},{"n":416,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"القيم والرموز الحضارية","stem":"منتجع سياحي في تايلند يعلن للعوائل الخليجية: «وجبات حلال ١٠٠٪ ومصليات في كل مبنى». وش استراتيجية الموقع التنافسي هنا؟","options":["تصميم الموقع التنافسي طبقاً للحاجات النفسية للمستهلكين","تحديد الموقع التنافسي طبقاً لنوع أو فئة المنتج","تصميم الموقع باستخدام القيم والرموز الحضارية (Positioning by cultural values / Symbols)","تحديد الموقع التنافسي بالمقارنة المباشرة مع المنافسين"],"answer":2,"why":"شريحة 26: تعتمد على «استغلال إحدى القيم الحضارية أو الدينية أو الروحية أو العادات أو التقاليد السائدة بالمجتمع». ومثالها السياحي في الشريحة: الخطوط الجوية البريطانية «تمتع بالوجبات الشهية الحلال عند ما تسافر الى لندن»، وشركة التعاون الإسلامي بدبي (لحوم مذبوحة حسب الشريعة).","wrong":[{"i":0,"mis":"gen.neighbor","note":"الحاجات النفسية = تقدير الذات وتحقيق الذات (فخامة، ثقة بالنفس)، مو قيمة دينية."},{"i":1,"mis":"gen.neighbor","note":"فئة المنتج = استغلال نوع وطبيعة المنتج نفسه (القهوة سريعة الذوبان، ش25)."},{"i":3,"mis":"gen.neighbor","note":"ما فيه مقارنة مع علامة منافسة."}],"tests":["Positioning by cultural values / Symbols","مثال الخطوط الجوية البريطانية"]},{"n":417,"lo":"CH4","sec":"MKT231-CH4","type":"tf","topic":"المقارنة مع المنافسين","stem":"في استراتيجية المقارنة المباشرة مع المنافسين، غالباً تكون العلامة اللي تقارن فيها الشركة نفسها أقوى منافس في السوق، ومن أسباب كذا إن الشركة تقدر تستغل الصورة الذهنية اللي أنشأها المنافس لصالح علامتها.","options":["صح","خطأ"],"answer":0,"why":"صح. شريحة 28: «وغالباً ما تكون العلامة المذكورة أقوى منافس في السوق ولذلك سببان»: (١) استغلال الصورة الذهنية اللي أنشأها المنافسون لصالح علامة الشركة ثم إرساء صورة أفضل (٢) المهم إن المستهلك يعتقد إن الشركة أفضل من منافسيها (بطريقة المقارنة)، مو القدر العالي بصورة مجردة.","wrong":[{"i":1,"mis":"k4.weak-looks-good","note":"اللي يقول خطأ غالباً خلط بينها وبين «مهاجمة الموقع التنافسي لعلامة الشركة القائدة» (سبب ضعف، ش15). المقارنة المباشرة استراتيجية رسمية في ش28."}],"tests":["Positioning with respect to a competitor","سببا المقارنة مع أقوى منافس"]},{"n":418,"lo":"CH4","sec":"MKT231-CH4","type":"scenario","topic":"طرق قياس الموقع","stem":"شركة سياحة جمعت ٨ مسافرين في جلسة نقاش وحدة مع منسّق، يتكلمون مع بعض عن انطباعهم عن علامتها وعلامات المنافسين. هذي أي طريقة من طرق البحث لتقرير الموقع التنافسي (شريحة 29)؟","options":["المقابلات الشخصية المتعمقة (Depth interviews)","الخرائط الإدراكية (Perceptual Maps)","القياس متعدد الأبعاد (Multi dimensional scaling)","المقابلات الجماعية المركزة / جماعات التركيز (Focus Groups)"],"answer":3,"why":"شريحة 29: من طرق البحث «المقابلات الجماعية المركزة أو (جماعات التركيز Focus Groups)» و«المقابلات الشخصية المتعمقة Depth interviews» والاستبيانات والتجارب. جلسة جماعية = جماعات التركيز؛ مقابلة فرد بفرد = المقابلات الشخصية المتعمقة.","wrong":[{"i":0,"mis":"gen.keyword","note":"«شخصية متعمقة» يعني مقابلة فرد بفرد، والقصة جلسة جماعية."},{"i":1,"mis":"gen.neighbor","note":"الخريطة الإدراكية شكل بياني يُرسم من بيانات الاستبانة (ش33)، مو جلسة نقاش."},{"i":2,"mis":"k4.steps-order","note":"القياس متعدد الأبعاد أسلوب إحصائي في خطوة التحليل من إعداد الخريطة (ش34)، مو طريقة جمع آراء."}],"tests":["Focus Groups","Depth interviews","طرق قياس الموقع التنافسي"]},{"n":419,"lo":"CH4","sec":"MKT231-CH4","type":"list","topic":"خطوات تصميم الموقع","stem":"أي ربط صحيح بين رقم الخطوة واسمها في خطوات تصميم الموقع التنافسي للمنتج (٦ خطوات)؟","options":["الخطوة الأولى: تحديد الخصائص الحاسمة للمنتج","الخطوة الثانية: تحديد المواقع التنافسية للمنتجات والعلامات المنافسة","الخطوة الثالثة: اختيار الموقع التنافسي لعلامة الشركة","الخطوة السادسة: تحليل خصائص المستهلكين"],"answer":1,"why":"شرائح 30–32، الخطوات الست بالترتيب: (١) تحليل المنافسة وتحديد المنافسين (٢) تحديد المواقع التنافسية للمنتجات والعلامات المنافسة، وفيها تنعمل الخريطة الإدراكية (٣) تحليل خصائص المستهلكين (٤) تحديد الخصائص الحاسمة للمنتج (٥) اختيار الموقع التنافسي لعلامة الشركة (٦) متابعة الموقع التنافسي المختار.","wrong":[{"i":0,"mis":"k4.steps-order","note":"الخصائص الحاسمة = الخطوة الرابعة؛ الأولى تحليل المنافسة وتحديد المنافسين."},{"i":2,"mis":"k4.steps-order","note":"الاختيار = الخطوة الخامسة؛ الثالثة تحليل خصائص المستهلكين."},{"i":3,"mis":"k4.steps-order","note":"السادسة = متابعة الموقع المختار؛ تحليل خصائص المستهلكين هي الثالثة."}],"tests":["خطوات تصميم الموقع التنافسي الست"]},{"n":420,"lo":"CH4","sec":"MKT231-CH4","type":"tf","topic":"الخصائص الحاسمة","stem":"عشان تعتبر خاصية من خصائص المنتج «خاصية حاسمة» (Determinant Attribute)، يكفي إنها تكون هامة من وجهة نظر المستهلكين حتى لو كل العلامات في السوق متشابهة فيها.","options":["صح","خطأ"],"answer":1,"why":"خطأ. شريحة 31: الخصائص الحاسمة «أي خصائص المنتج التي يستخدمها المستهلك في اختيار علامة بعينها دون غيرها من العلامات»، ولازم شرطين مع بعض: تكون «هامة من وجهة نظر المستهلكين» و«يشعر المستهلكون بوجود اختلافات بخصوصها فيما بين العلامات التجارية».","wrong":[{"i":0,"mis":"k4.determinant-attributes","note":"الأهمية لحالها ما تكفي؛ لو كل العلامات متشابهة فيها ما تفرّق بينها، فما تكون حاسمة."}],"tests":["الخصائص الحاسمة للمنتج (Determinant Attributes)"]},{"n":421,"lo":"CH4","sec":"MKT231-CH4","type":"list","topic":"خطوات إعداد الخريطة الإدراكية","stem":"يمر إعداد الخرائط الإدراكية بأربع خطوات. وش الترتيب الصحيح؟","options":["جمع البيانات ← إعداد الاستبانة ← رسم الخريطة ← التحليل الإحصائي","إعداد الاستبانة ← التحليل الإحصائي ← جمع البيانات ← رسم الخريطة","إعداد الاستبانة ← جمع البيانات ← التحليل الإحصائي (القياس متعدد الأبعاد) ← رسم الخريطة الإدراكية","تحليل المنافسة ← تحديد مواقع المنافسين ← تحليل خصائص المستهلكين ← رسم الخريطة"],"answer":2,"why":"شرائح 33–34: (١) إعداد الاستبانة (٢) جمع البيانات من عينة ممثلة للسوق المستهدف (٣) التحليل الإحصائي باستخدام «القياس متعدد الأبعاد Multi dimensional scaling» (٤) رسم الخريطة الادراكية، وأبسطها ذات البعدين.","wrong":[{"i":0,"mis":"k4.steps-order","note":"ما تقدر تجمع بيانات قبل ما تعد الاستبانة، والرسم آخر شي بعد التحليل."},{"i":1,"mis":"k4.steps-order","note":"التحليل الإحصائي يجي بعد جمع البيانات مو قبله."},{"i":3,"mis":"k4.steps-order","note":"هذي بداية خطوات تصميم الموقع التنافسي الست (ش30–31)، مو خطوات إعداد الخريطة."}],"tests":["خطوات إعداد الخريطة الإدراكية","القياس متعدد الأبعاد (Multi dimensional scaling)"]},{"n":422,"lo":"CH4","sec":"MKT231-CH4","type":"concept","topic":"الخريطة الإدراكية","stem":"أي عبارة صحيحة عن الخريطة الإدراكية (Perceptual Map)؟","options":["شكل بياني يعكس كيف يتصور المستهلكون مجموعة العلامات المتنافسة (ومنها علامة الشركة) طبقاً لخصائصها الحاسمة، ومن فوائدها الكشف عن الفرص التسويقية لتقديم منتجات جديدة","أسلوب إحصائي يساعد في الحصول على أحسن تطابق ممكن بين تقديرات المستهلكين، وأبسط أنواعها الخريطة ذات الثلاث أبعاد","التقييم الشخصي للمستهلك للمزايا والفوائد والمنافع اللي يتصور حصوله عليها، وتتكون في مخيلته بدون أي بحث","طريقة بحث تجمع مجموعة مستهلكين في مقابلة جماعية مركزة، وتُستخدم في الخطوة السادسة من خطوات التصميم"],"answer":0,"why":"شريحة 33: «هى شكل بياني يعكس كيفية تصور المستهلكين لمجموعة من المنتجات أو العلامات المتنافسة بما فيها علامة الشركة طبقاً لخصائصها الحاسمة». وشريحة 35 تذكر ٥ فوائد، منها «الكشف عن الفرص التسويقية التي تسمح بتقديم منتجات جديدة»، والباقي: التعرف على موقع العلامة، التحقق من توجيه الجهود للقطاع المناسب، الحجم الحقيقي للمنافسة، وتقييم الموقع مقارنة بالعلامة المثالية.","wrong":[{"i":1,"mis":"gen.detail","note":"هذا وصف القياس متعدد الأبعاد (ش34)، وأبسط خريطة هي ذات البعدين مو الثلاث."},{"i":2,"mis":"k4.position-vs-image","note":"هذا تعريف الصورة الذهنية (ش9)، والخريطة تحتاج استبانة وتحليل إحصائي."},{"i":3,"mis":"gen.neighbor","note":"هذي جماعات التركيز، طريقة بحث (ش29)، والخطوة السادسة هي المتابعة."}],"tests":["الخريطة الإدراكية (Perceptual Map)","فوائد الخرائط الإدراكية الخمس"]},{"n":501,"lo":"CH5","sec":"MKT231-CH5","type":"term","topic":"تعريف ثقافة المجتمع","stem":"«مجموعة القيم والعادات والتقاليد والمعتقدات السائدة في مجتمع ما وكذلك النتاج المادي الذي يعكسها وأية رموز أخرى ذات معنى...» هذا تعريف:","options":["القيم الجوهرية للمجتمع","التطبيع الاجتماعي","الثقافة أو الحضارة","التطبيع الاستهلاكي"],"answer":2,"why":"شريحة 6: هذا تعريف الثقافة أو الحضارة بالنص. لاحظ يجمع 3 أشياء: القيم والعادات والتقاليد والمعتقدات، النتاج المادي، والرموز.","wrong":[{"i":0,"mis":"gen.neighbor","note":"القيم الجوهرية جزء من الثقافة: معتقدات ومعايير يلتزم بها الكل (ش8)، ما فيها النتاج المادي"},{"i":1,"mis":"gen.neighbor","note":"التطبيع الاجتماعي عملية تعلّم الثقافة (ش9)، مو الثقافة نفسها"},{"i":3,"mis":"k5.social-vs-consumer-socialization","note":"التطبيع الاستهلاكي = اكتساب المعرفة بالسوق (ش10)"}],"tests":["تعريف الثقافة أو الحضارة"]},{"n":502,"lo":"CH5","sec":"MKT231-CH5","type":"concept","topic":"عنصرا الحضارة والاستعمال الشائع","stem":"الحضارة تتكون من عنصرين أساسيين، بس الشائع لما نستعمل كلمة «الثقافة أو الحضارة» نقصد فيها:","options":["الجانب المادي فقط زي المباني والسيارات","الجانب المعنوي أو التجريدي فقط دون الجانب المادي","الجانبين المعنوي والمادي مع بعض","الرموز ذات المعنى فقط"],"answer":1,"why":"شريحة 6: «ومن الشائع استعمال اصطلاح الثقافة أو الحضارة للتعبير عن الجانب المعنوي أو التجريدي فقط دون الجانب المادي».","wrong":[{"i":0,"mis":"k5.culture-common-usage","note":"بالعكس: المادي هو المستبعد في الاستعمال الشائع"},{"i":2,"mis":"gen.partial","note":"التعريف الكامل فيه الاثنين، بس السؤال عن الاستعمال الشائع"},{"i":3,"mis":"gen.detail","note":"الرموز جزء من التعريف، مو هي المقصودة بالاستعمال الشائع"}],"tests":["العنصر المعنوي والعنصر المادي","الاستعمال الشائع لاصطلاح الثقافة"]},{"n":503,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"القيم الجوهرية والقيم الفردية","stem":"سائح سعودي مسافر لدبي لابس ثوب أبيض زي أغلب السعوديين، بس اختار تصميم قطري للثوب لأنه يعجبه هو. حسب شريحة 8:","options":["لبس الثوب الأبيض قيمة جوهرية، وتصميمه القطري قيمة فردية","لبس الثوب الأبيض قيمة فردية، وتصميمه القطري قيمة جوهرية","الاثنين قيم جوهرية لأنها من عادات المجتمع","الاثنين قيم فردية لأنها اختيارات شخصية"],"answer":0,"why":"شريحة 8: «فمثلاً ارتداء الثوب الأبيض قيمة اجتماعية أساسية عند السعوديين. تصميم الثوب حجازي أو قطري قيمة فردية.» الجوهرية للمجتمع كله وملزمة، والفردية خاصة بالشخص.","wrong":[{"i":1,"mis":"gen.reversed","note":"قلب مثال الشريحة"},{"i":2,"mis":"k5.core-vs-individual","note":"التصميم خاص بالشخص وما يشاركه فيه باقي المجتمع"},{"i":3,"mis":"k5.core-vs-individual","note":"لبس الأبيض يؤمن به جميع أفراد المجتمع وملزم لهم"}],"tests":["القيم الجوهرية","القيم الفردية"]},{"n":504,"lo":"CH5","sec":"MKT231-CH5","type":"term","topic":"التطبيع الاستهلاكي","stem":"العملية اللي «يكتسب الفرد من خلالها معرفته بالسوق وتتشكل دوافعه الشرائية واتجاهاته النفسية وميوله ومواقفه تجاه الشركات المنتجة والمحلات التجارية...» اسمها:","options":["التطبيع الاجتماعي (Socialization)","القيم الجوهرية (Core values)","الثقافة (Culture)","التطبيع الاستهلاكي (Consumer Socialization)"],"answer":3,"why":"شريحة 10: هذي التنشئة الاستهلاكية أو التطبيع الاستهلاكي (Consumer Socialization)، وهي «امتداداً لعملية التطبيع الاجتماعي».","wrong":[{"i":0,"mis":"k5.social-vs-consumer-socialization","note":"الاجتماعي أعم: تكيّف الفرد مع عادات وحاجات المجتمع، والاستهلاكي امتداده الخاص بالسوق"},{"i":1,"mis":"gen.neighbor","note":"القيم الجوهرية معتقدات ومعايير المجتمع، مو عملية اكتساب"},{"i":2,"mis":"gen.neighbor","note":"الثقافة هي اللي نتعلمها، مو عملية التعلم في السوق"}],"tests":["التطبيع الاستهلاكي","التطبيع الاجتماعي"]},{"n":505,"lo":"CH5","sec":"MKT231-CH5","type":"tf","topic":"التطبيع الاجتماعي","stem":"عملية التطبيع الاجتماعي تبدأ في مرحلة الطفولة وتنتهي بانتهائها.","options":["صح","خطأ"],"answer":1,"why":"شريحة 9: «وعادة ما تبدأ هذه العملية في مرحلة الطفولة وتستمر طوال حياة الفرد». البداية صح، بس ما تنتهي.","wrong":[{"i":0,"mis":"k5.socialization-childhood-only","note":"نصف الجملة صح (البداية)، والنهاية غلط: تستمر طول العمر"}],"tests":["التطبيع الاجتماعي: بدايته واستمراره"]},{"n":506,"lo":"CH5","sec":"MKT231-CH5","type":"list","topic":"السلوكيات والنزعات المتأثرة بالثقافة","stem":"أي واحد من هذي مذكور في قائمة شريحة 7 (أهم السلوكيات والنزعات اللي تتأثر بثقافة المجتمع)؟","options":["تكريس وقت أقل للأطفال","النظرة الى الوقت وأهميته والاحساس به","الزيادة المستمرة في عدد الملتحقين بالمدارس والجامعات","ارتفاع معدلات الطلاق"],"answer":1,"why":"شريحة 7 فيها 10 بنود، منها «النظرة الى الوقت وأهميته والاحساس به». الخيارات الثانية من تغيرات الأسرة (ش31) والتعليم (ش33).","wrong":[{"i":0,"mis":"gen.neighbor","note":"عامل قلّص تأثير الأسرة (ش31)"},{"i":2,"mis":"gen.neighbor","note":"سبب لزيادة أثر التعليم (ش33)"},{"i":3,"mis":"gen.neighbor","note":"عامل قلّص تأثير الأسرة (ش31)"}],"tests":["السلوكيات والنزعات المتأثرة بالثقافة (10)"]},{"n":507,"lo":"CH5","sec":"MKT231-CH5","type":"list","topic":"الخصائص العامة للثقافة","stem":"أي واحد من هذي مو من الخصائص العامة الأربع للثقافة؟","options":["توارث الثقافة عبر الأجيال","الثقافة وسيلة لتحقيق الاشباع الاجتماعي","الثقافة سلوك غريزي تلقائي يولد مع الإنسان","تكيف الثقافة مع التغيير في بعض القيم في الأجل الطويل"],"answer":2,"why":"الخصائص الأربع (ش11–15): تعلم الفرد لثقافة مجتمعه، توارثها عبر الأجيال، تكيفها مع التغيير في بعض القيم في الأجل الطويل، والثقافة وسيلة للإشباع الاجتماعي. وشريحة 12 تقول بالعكس: سلوك بني آدم «غير تلقائي وغير غريزي».","wrong":[{"i":0,"mis":"k5.characteristics-mixup","note":"هذي الخاصية الثانية (ش13)"},{"i":1,"mis":"k5.characteristics-mixup","note":"هذي الخاصية الرابعة (ش15)"},{"i":3,"mis":"k5.characteristics-mixup","note":"هذي الخاصية الثالثة (ش14)"}],"tests":["الخصائص العامة للثقافة (4)","تعلم الثقافة غير غريزي"]},{"n":508,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"الثقافة وسيلة لتحقيق الإشباع الاجتماعي","stem":"معظم المستهلكين الأمريكيين انصرفوا عن أكل اللحوم والبطاطس لما زادت الوظائف المكتبية وقلّت حاجتهم للسعرات الحرارية العالية. الشرائح ذكرت هذا المثال تحت أي خاصية من خصائص الثقافة؟","options":["تعلم الفرد لثقافة مجتمعه","توارث الثقافة عبر الأجيال","تكيف الثقافة مع التغيير في بعض القيم في الأجل الطويل","الثقافة وسيلة لتحقيق الاشباع الاجتماعي"],"answer":3,"why":"شريحة 15: لما تعجز قيمة أو قاعدة سلوكية عن إمداد الأفراد بالإشباع الاجتماعي «تبدأ تلك القيمة أو القاعدة السلوكية في الانحسار والاختفاء»، ومثالها اللحوم والبطاطس.","wrong":[{"i":0,"mis":"gen.neighbor","note":"التعلم عن طرق اكتساب الثقافة (توجيه، تقليد، تجربة وخطأ)"},{"i":1,"mis":"gen.neighbor","note":"التوارث عن انتقال الثقافة عن طريق المؤسسات الاجتماعية"},{"i":2,"mis":"k5.satisfaction-vs-change","note":"قريبة، بس الشريحة حاطة المثال تحت الإشباع: العادة انحسرت لأنها ما عادت تشبع الحاجة"}],"tests":["الثقافة وسيلة لتحقيق الإشباع الاجتماعي","مثال اللحوم والبطاطس"]},{"n":509,"lo":"CH5","sec":"MKT231-CH5","type":"list","topic":"جوانب تأثر سلوك المستهلكين بثقافة مجتمعهم","stem":"ثقافة المجتمع تشكّل السلوك الشرائي والاستهلاكي من خمس جوانب. أي واحد من هذي مو منها؟","options":["تحديد أسعار المنتجات المعروضة في السوق","تحديد الهيكل الاستهلاكي للمجتمع وفلسفته الاستهلاكية","صياغة أساليب الاتصال بين أفراد المجتمع","تحديد الأسباب التي من أجلها يشتري المستهلكون تلك المنتجات"],"answer":0,"why":"شريحة 16: الخمسة = الهيكل الاستهلاكي وفلسفته، نوعية المنتجات المسموح ببيعها، أسباب الشراء، التأثير في اتخاذ القرارات الشرائية، صياغة أساليب الاتصال. تحديد الأسعار مو منها.","wrong":[{"i":1,"mis":"k5.lists-mixup","note":"هذا الجانب الأول (ش17)"},{"i":2,"mis":"k5.lists-mixup","note":"هذا الجانب الخامس (ش23)"},{"i":3,"mis":"k5.lists-mixup","note":"هذا الجانب الثالث (ش19)"}],"tests":["جوانب تأثر سلوك المستهلكين بالثقافة (5)"]},{"n":510,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"تحديد نوعية المنتجات المباعة داخل المجتمع","stem":"شركة سياحة تنظّم رحلة لمجموعة هندوسية، وشالت كل وجبات لحم البقر من البرنامج لأن ثقافتهم تحرم ذبح البقر وأكله. هذا مثال على أي جانب من جوانب تأثر سلوك المستهلكين بثقافة مجتمعهم؟","options":["التأثير في عملية اتخاذ القرارات الشرائية","تحديد نوعية المنتجات المباعة داخل المجتمع","صياغة أساليب الاتصال بين أفراد المجتمع","الهيئة التي تستهلك بها السلعة"],"answer":1,"why":"شريحة 18: «وتحرم الثقافة الهندوسية ذبح البقر وأكله وتعتبره من المخلوقات المقدسة»، مثال على الجانب الثاني: كل ثقافة تحدد نوعية المنتجات اللي «يتحتم عليهم استهلاكها من عدمه».","wrong":[{"i":0,"mis":"gen.neighbor","note":"الجانب الرابع عن مراحل القرار ومصلحة الجماعة أو الفرد"},{"i":2,"mis":"gen.neighbor","note":"الجانب الخامس عن المعاني الاجتماعية للمنتجات"},{"i":3,"mis":"k5.lists-mixup","note":"الهيئة سبب شراء عن شكل الاستهلاك (نيئ أو مطهي)، مو منع المنتج كله"}],"tests":["تحديد نوعية المنتجات المباعة داخل المجتمع","أمثلة الثقافات: الإسلامية والهندوسية والصينية"]},{"n":511,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"أسباب الشراء: الهيئة","stem":"سائح ياباني في جدة طلب سمك نيئ زي ما متعود في بلده، والمطعم ما يقدم السمك إلا مطبوخ لأن العرب ما ياكلونه إلا مطهي. هذا مثال على أي سبب من أسباب الشراء الثلاثة؟","options":["الأداء الوظيفي للسلعة","السلع كرموز حضارية","الهيئة التي تستهلك بها السلعة","تحديد نوعية المنتجات المباعة داخل المجتمع"],"answer":2,"why":"شريحة 19: تحت (ب) الهيئة اللي تستهلك بها السلعة: اليابانيون «يفضلون أكل السمك نيئاً» والعرب «لا يأكلونه إلا مطهياً». السمك نفسه مسموح، الفرق في شكل استهلاكه.","wrong":[{"i":0,"mis":"k5.three-reasons-mixup","note":"الأداء الوظيفي = المهمة المتوقعة ومستواها، زي جودة المنتجات اليابانية"},{"i":1,"mis":"k5.three-reasons-mixup","note":"الرموز الحضارية = وش تعني السلعة للمجتمع، زي الكبسة والعزايم"},{"i":3,"mis":"k5.lists-mixup","note":"السمك مو ممنوع، فهذا مو جانب نوعية المنتجات"}],"tests":["أسباب الشراء الثلاثة","الهيئة التي تستهلك بها السلعة"]},{"n":512,"lo":"CH5","sec":"MKT231-CH5","type":"concept","topic":"فلسفة الاستهلاك: الغربية مقابل الإسلامية","stem":"حسب شريحة 17، الفلسفة الاستهلاكية في المجتمعات الإسلامية:","options":["تتركز حول الرفاهية المادية وتستهدف تعظيم الاستهلاك الاستمتاعي في الدنيا","تقلل من المبالغة في الاستغراق في الاستمتاع المادي وتطالب الفرد بالتوازن مع الجانب الروحي","تشجع التنافس وتعطي المصلحة الشخصية جانب أكبر من الأهمية","تمنع الاستهلاك الترفي تماماً وتلغي الفروق بين الطبقات"],"answer":1,"why":"شريحة 17: الفلسفة الإسلامية «تقلل ... من شأن المبالغة في الاستغراق في الاستمتاع المادي وتطالب الفرد بالحفاظ على نوع من التوازن بينه وبين الجانب الروحي من حياته». الرفاهية المادية وتعظيم الاستهلاك الاستمتاعي للغرب.","wrong":[{"i":0,"mis":"k5.islamic-vs-western","note":"هذي فلسفة المجتمعات الغربية"},{"i":2,"mis":"k5.islamic-vs-western","note":"هذي الحضارة الأمريكية في القرار الشرائي (ش21)"},{"i":3,"mis":"gen.absolute","note":"مبالغة: الإسلامية تقلل المبالغة مو تمنع، ورفض الترفي وتضاؤل الفروق قيلت عن اليابانية (ش28)"}],"tests":["فلسفة الاستهلاك: الغربية مقابل الإسلامية","الجانب الأول: الهيكل الاستهلاكي والفلسفة الاستهلاكية"]},{"n":513,"lo":"CH5","sec":"MKT231-CH5","type":"term","topic":"القيم النهائية والوسيطة","stem":"في الاستقصاء اللي صممه الباحثون للتعرف على قيم الأفراد (جدول 5-2)، القيم اللي تمثل «الحالات النهائية التي يود الفرد أن يصل اليها (أي الغايات)» وش اسمها وكم عددها؟","options":["القيم الوسيطة — 18 قيمة","القيم النهائية — 9 قيم","القيم الجوهرية — 36 قيمة","القيم النهائية — 18 قيمة"],"answer":3,"why":"شريحة 24: الاستقصاء مجموعتين: النهائية (الغايات) والوسيطة (الوسائل)، و«تتكون كل مجموعة منهما من (18) قيمة».","wrong":[{"i":0,"mis":"k5.terminal-vs-instrumental","note":"الوسيطة = الوسائل، مو الغايات"},{"i":1,"mis":"k5.terminal-vs-instrumental","note":"الاسم صح والعدد غلط: كل مجموعة 18"},{"i":2,"mis":"gen.neighbor","note":"الاستقصاء فيه نهائية ووسيطة، و36 هو مجموع المجموعتين"}],"tests":["القيم النهائية","عدد القيم في الاستقصاء"]},{"n":514,"lo":"CH5","sec":"MKT231-CH5","type":"concept","topic":"دور القيم النهائية والوسيطة في الاختيار","stem":"حسب شريحة 25، القيم الوسيطة تأثر في:","options":["الاختيار من بين فئات المنتجات","تحديد الحالات النهائية اللي يبي الفرد يوصل لها","عملية الاختيار بين العلامات التجارية","تحديد نوعية المنتجات المسموح ببيعها"],"answer":2,"why":"شريحة 25: «القيم النهائية تلعب الدور الاساسي في الاختيار من بين فئات المنتجات بينما تؤثر القيم الوسيطة في عملية الاختيار بين العلامات التجارية».","wrong":[{"i":0,"mis":"k5.terminal-vs-instrumental","note":"هذا دور القيم النهائية"},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف القيم النهائية نفسها (الغايات)"},{"i":3,"mis":"k5.lists-mixup","note":"هذا جانب من تأثير الثقافة على المستهلك (ش16)"}],"tests":["القيم الوسيطة","دور القيم النهائية والوسيطة في الاختيار"]},{"n":515,"lo":"CH5","sec":"MKT231-CH5","type":"tf","topic":"الثقافة عامل بيئي","stem":"ثقافة المجتمع من العوامل النفسية المؤثرة في سلوك المستهلك.","options":["صح","خطأ"],"answer":1,"why":"شريحة 2: الفصل تحت «القسم الثالث: العوامل البيئية المؤثرة في سلوك المستهلك»، وشريحة 21: «تعتبر ثقافة المجتمع من أهم العوامل البيئية». النفسية في القسم الرابع (الدوافع، الإدراك، التعلم، الاتجاهات).","wrong":[{"i":0,"mis":"k5.culture-is-psych","note":"الثقافة عامل بيئي مو نفسي"}],"tests":["الثقافة عامل بيئي"]},{"n":516,"lo":"CH5","sec":"MKT231-CH5","type":"list","topic":"التغيرات الاجتماعية المعاصرة","stem":"حسب شريحة 30، أهم التغيرات الاجتماعية المعاصرة هي اللي تجتاح ثلاث مؤسسات اجتماعية هامة، وهي:","options":["الأسرة والدين والتعليم","الأسرة والمدرسة ووسائل الإعلام","الأسرة والتعليم وثقافة الاستهلاك","الدين والجامعة والأصدقاء"],"answer":0,"why":"شريحة 30: «تجتاح ثلاث مؤسسات اجتماعية هامة هى الأسرة والدين والتعليم». التحول لثقافة الاستهلاك (ش35) بند رابع بس مو مؤسسة.","wrong":[{"i":1,"mis":"k5.three-institutions-four-items","note":"خلط مع مؤسسات توارث الثقافة (ش13)"},{"i":2,"mis":"k5.three-institutions-four-items","note":"ثقافة الاستهلاك بند رابع مو مؤسسة"},{"i":3,"mis":"gen.neighbor","note":"الجامعة من مؤسسات التوارث، والأصدقاء يساهمون في صقل الثقافة (ش13)"}],"tests":["التغيرات الاجتماعية المعاصرة: المؤسسات الثلاث"]},{"n":517,"lo":"CH5","sec":"MKT231-CH5","type":"list","topic":"التغيرات المتعلقة بالأسرة","stem":"أي واحد من هذي مو من العوامل اللي ساهمت في تقليص تأثير الأسرة على أطفالها (شريحة 31)؟","options":["استخدام الأساليب التعليمية الحديثة","ارتفاع معدلات الطلاق","تعدد الزوجات","التفتت العائلي"],"answer":0,"why":"شريحة 31 فيها 4 عوامل: تكريس وقت أقل للأطفال، ارتفاع معدلات الطلاق، تعدد الزوجات، التفتت العائلي. الأساليب التعليمية الحديثة من تغيرات التعليم (ش34).","wrong":[{"i":1,"mis":"gen.detail","note":"هذا من العوامل الأربعة فعلاً (ش31)"},{"i":2,"mis":"gen.detail","note":"هذا من العوامل الأربعة فعلاً (ش31)"},{"i":3,"mis":"gen.detail","note":"هذا من العوامل الأربعة فعلاً (ش31)"}],"tests":["التغيرات المتعلقة بالأسرة (4 عوامل)"]},{"n":518,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"تغير المؤسسات التعليمية","stem":"فندق في العلا لاحظ النزلاء صاروا أجرأ: يحاسبونه على أخطائه ويكتبون عنه تقييمات سلبية تضر سمعته. الشرائح تربط هذا بتغير المؤسسات التعليمية. وش المطلوب من مسؤولي التسويق في الفندق؟","options":["يتجاهلون التقييمات لأنها ما تأثر على سمعة الفندق ولا مبيعاته","يحاولون يغيرون قيم النزلاء عشان يتقبلون أخطاء الفندق","يركزون على الأداء الوظيفي للخدمة ويتركون التواصل مع النزلاء","حرص ويقظة عالية، ومعلومات للعملاء، وقنوات تنقل الشكاوى والرد عليها دون تأخير"],"answer":3,"why":"شريحة 34: الأساليب التعليمية الحديثة خلّت المستهلكين «أكثر جرأة في معاملة منشآت الأعمال وفي محاسبتها على أخطائها»، والمطلوب من مسؤولي التسويق الحرص واليقظة وإمداد العملاء بالمعلومات وتوفير قنوات تنقل الشكاوى والرد عليها «دون عناء أو تأخير».","wrong":[{"i":0,"mis":"gen.reversed","note":"الشريحة تقول الكلام السلبي «يضر بسمعة الشركة ضرراً بالغاً ويخفض من مبيعاتها»"},{"i":1,"mis":"k5.change-values","note":"الاستراتيجية تعكس القيم بدل ما تحاول تغيرها (ش25)"},{"i":2,"mis":"gen.neighbor","note":"الأداء الوظيفي سبب شراء (ش19)، والشريحة تطلب العكس: تواصل وقنوات شكاوى"}],"tests":["تغير المؤسسات التعليمية","دور مسؤولي التسويق مع المستهلك الأجرأ"]},{"n":519,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"التحول الى ثقافة الاستهلاك","stem":"مجتمع خليجي اقتصاده يمر بنهضة ونمو سريعين، ودخل أفراده يزيد بصورة مطردة، وصاروا يصرفون على السفر الفاخر والسلع الترفيهية والمعمرة بمعدلات تساوي أو تفوق زيادة الدخل. الشرائح تسمي هذا:","options":["التحول الى ثقافة الاستهلاك","التطبيع الاستهلاكي","الثقافة وسيلة لتحقيق الاشباع الاجتماعي","تغير المؤسسات الدينية"],"answer":0,"why":"شريحة 35: «في ظل هذه الظروف تسيطر على أفراد المجتمع ما يمكن أن نسميه بثقافة الاستهلاك»، ولو استمر لفترة طويلة ممكن يغير بعض القيم الحضارية للمجتمع ككل.","wrong":[{"i":1,"mis":"k5.social-vs-consumer-socialization","note":"التطبيع الاستهلاكي = اكتساب المعرفة بالسوق وتشكل الدوافع، مو زيادة الإنفاق البذخي"},{"i":2,"mis":"gen.neighbor","note":"خاصية من خصائص الثقافة عن بقاء القيم اللي تشبع الحاجة (ش15)"},{"i":3,"mis":"gen.neighbor","note":"تغير المؤسسات الدينية عن الطقوس ومواسم البيع (ش32)"}],"tests":["التحول إلى ثقافة الاستهلاك"]},{"n":520,"lo":"CH5","sec":"MKT231-CH5","type":"scenario","topic":"تأثر النشاط التسويقي بالقيم الجوهرية","stem":"سلسلة مطاعم في موسم الرياض كتبت على إعلاناتها وعبواتها: «دواجننا مذبوحة بالطريقة الإسلامية». هذا يمثل أي مجال من مجالات استفادة مدير التسويق من القيم الجوهرية؟","options":["تصميم المنتجات واستخداماتها بما يتفق مع القيم الأساسية للمجتمع","فهم طرق الاتصال وطبيعة العلاقات بين المتعاملين في السوق","صياغة أساليب الاتصال بين أفراد المجتمع","استخدام القيم الأساسية للمجتمع في خلق تصور إيجابي عن المنتجات"],"answer":3,"why":"شريحة 37: «ومن أبرز الأمثلة على ذلك تأكيد بعض شركات إنتاج الدواجن في إعلاناتها وعلى عبواتها على أن دواجنها مذبوحة بالطريقة الاسلامية»، وهذا المجال الثاني.","wrong":[{"i":0,"mis":"k5.marketing-areas-mixup","note":"المجال الأول عن تصميم المنتج وطرق استخدامه (الخلطات والإعداد ووقت التناول)"},{"i":1,"mis":"k5.marketing-areas-mixup","note":"المجال الثالث عن التسويق الدولي وفهم بيئة الأعمال الأجنبية"},{"i":2,"mis":"k5.lists-mixup","note":"هذا الجانب الخامس من تأثير الثقافة على المستهلك، مو من مجالات النشاط التسويقي"}],"tests":["مجالات استفادة مديري التسويق من القيم الجوهرية (3)","خلق تصور إيجابي عن المنتجات"]},{"n":521,"lo":"CH5","sec":"MKT231-CH5","type":"tf","topic":"الاستراتيجية التسويقية والقيم","stem":"حسب الشرائح، الاستراتيجية التسويقية الفعالة لازم تعكس القيم الحضارية السائدة في المجتمع بدل ما تحاول تغيرها.","options":["صح","خطأ"],"answer":0,"why":"شريحة 25: «فإن الاستراتيجية التسويقية الفعالة يجب أن تعكس تلك القيم بدلاً من أن تحاول تغييرها».","wrong":[{"i":1,"mis":"k5.change-values","note":"التسويق يتكيف مع القيم، ما يحاول يغيرها"}],"tests":["الاستراتيجية التسويقية والقيم الحضارية"]},{"n":522,"lo":"CH5","sec":"MKT231-CH5","type":"tf","topic":"تأثر القرار الشرائي بثقافة المجتمع","stem":"يمتد تأثير المجتمع لجوانب من القرار الشرائي زي التفاوض على السعر، وحجم وطبيعة شكاوي المستهلكين، ومدى مشاركة الزوج أو الزوجة في اتخاذ القرار.","options":["صح","خطأ"],"answer":0,"why":"شريحة 22: تأثير المجتمع يمتد «الى جوانب كثيرة من عملية اتخاذ القرارات الشرائية والاستهلاكية بما في ذلك التفاوض على السعر»، ومعها حجم وطبيعة الشكاوى ومشاركة الزوج أو الزوجة، وقيود الأماكن العامة والأنواع والكميات والشراء بالجملة.","wrong":[{"i":1,"mis":"gen.partial","note":"الثلاثة كلها من قائمة شريحة 22 (6 بنود)"}],"tests":["تأثر القرار الشرائي بثقافة المجتمع","جوانب القرار اللي يمتد لها تأثير المجتمع"]},{"n":601,"lo":"CH6","sec":"MKT231-CH6","type":"term","topic":"تعريف الطبقات الاجتماعية","stem":"«الفئات السكانية المكونة للمجتمع مرتبة في شكل هرمي يعكس تدرج المراكز الاجتماعية لهذه الفئات فيما بينها». هذا تعريف وش؟","options":["المركز الاجتماعي (Social status)","الطبقات الاجتماعية (Social classes)","القيم الجوهرية (Core values)","طرق القياس ذات المتغيرات المتعددة"],"answer":1,"why":"ش6: هذا نص تعريف الطبقات الاجتماعية (Social classes)، وتكملته: أعضاء كل فئة يتشابهون في الخصائص والاهتمامات والرغبات والقيم، ويختلفون عن أعضاء الفئات الثانية.","wrong":[{"i":0,"mis":"k6.status-class-reversed","note":"المركز الاجتماعي هو اللي تحدده الطبقة (ش7)، مو الفئات المرتبة هرمياً نفسها."},{"i":2,"mis":"gen.neighbor","note":"القيم الجوهرية من الفصل الخامس: قيم المجتمع كله، مو فئات مرتبة."},{"i":3,"mis":"gen.neighbor","note":"هذي طرق لقياس الطبقة (ش17)، مو تعريف الطبقة."}],"tests":["تعريف الطبقات الاجتماعية","Social classes","اللي يتشابه فيه أعضاء الفئة (4)"]},{"n":602,"lo":"CH6","sec":"MKT231-CH6","type":"term","topic":"المركز الاجتماعي","stem":"حسب ش7، وش اللي يحدد المركز الاجتماعي (Social status) للفرد بين الناس؟","options":["الطبقة الاجتماعية اللي ينتمي لها الفرد","الاحترام اللي يعطونه الناس له، وهو اللي يحدد طبقته","وظيفة أبوه، وهذا شي حتمي ما يتغير أبد","محلات التجزئة اللي يرتادها"],"answer":0,"why":"ش7 تقول إن الطبقة اللي ينتمي لها الفرد «تحدد مركزه الاجتماعي (Social status) بين الناس». يعني الطبقة تجي أول وبعدين المركز. والمركز هو اللي يعكس توقعات المجتمع لأسلوب معيشته مقارنة بالطبقات الثانية، وهو بعد اللي يعطيه الاحترام.","wrong":[{"i":1,"mis":"k6.status-class-reversed","note":"قلبت الاتجاه. الاحترام يجي من المركز الاجتماعي حسب ش7، وما هو اللي يحدد الطبقة."},{"i":2,"mis":"k6.absolute-stability","note":"ش7 تقول الأبناء «في أغلب الأحوال» يكونون بطبقة آبائهم، والأسرة تقدر تنتقل لطبقة ثانية. يعني الثبات نسبي وما هو حتمي."},{"i":3,"mis":"gen.reversed","note":"المحلات اللي يرتادها نتيجة لمركزه الاجتماعي (ش8)، ما هي اللي تحدده."}],"tests":["المركز الاجتماعي","Social status","اللي يعكسه المركز الاجتماعي (2)"]},{"n":603,"lo":"CH6","sec":"MKT231-CH6","type":"tf","topic":"الثبات النسبي","stem":"صح أو خطأ: «الطبقات الاجتماعية تتميز بالثبات المطلق، والأسرة العادية ما تقدر أبداً تنتقل من طبقة لطبقة ثانية».","options":["صح","خطأ"],"answer":1,"why":"ش7: الطبقات تتميز «بالثبات النسبي» مو المطلق. الأبناء غالباً بطبقة الآباء، بس الأسرة العادية تقدر تنتقل لو توفرت لها الظروف المواتية، ومو بنفس السهولة في كل المجتمعات.","wrong":[{"i":0,"mis":"k6.absolute-stability","note":"«نسبي» يعني الانتقال ممكن. كلمة «أبداً» هي الفخ."}],"tests":["الثبات النسبي للطبقات","انتقال الأسرة بين الطبقات"]},{"n":604,"lo":"CH6","sec":"MKT231-CH6","type":"list","topic":"تأثير الطبقة على سلوك المستهلك","stem":"حسب ش8، المركز الاجتماعي وطبيعة الوظيفة ومستوى التعليم ومقدار الثروة والدخل كلها عوامل تشكل أسلوب الشراء وتأثر في أشياء ثانية. أي واحد من هذي مو منها؟","options":["نوعية السلع والخدمات اللي ينتقيها","محلات التجزئة اللي يرتادها","الكيفية اللي يستغل فيها وقت فراغه","عدد أطفاله في الأسرة"],"answer":3,"why":"ش8: العوامل «تشكل أسلوب شرائه وتؤثر في نوعية السلع والخدمات ... ومحلات التجزئة ... والطريقة التي يوزع بها دخله»، و«توجه» وقت الفراغ، و«تحدد» الهوايات والاهتمامات. عدد الأطفال ما انذكر أبداً.","wrong":[{"i":0,"mis":"gen.detail","note":"مذكورة: «تؤثر في نوعية السلع والخدمات التي ينتقيها»."},{"i":1,"mis":"gen.detail","note":"مذكورة: «ومحلات التجزئة التي يرتادها»."},{"i":2,"mis":"gen.detail","note":"مذكورة: «توجه الكيفية التي يستغل بها وقت فراغه»."}],"tests":["العوامل اللي تشكل أسلوب الشراء (5)","تأثيرات الطبقة على السلوك (6)"]},{"n":605,"lo":"CH6","sec":"MKT231-CH6","type":"concept","topic":"فايدة دراسة الطبقات","stem":"حسب ش9، وش الفايدة النهائية من دراسة خصائص الطبقات الاجتماعية وحجم كل منها داخل المجتمع؟","options":["تغيير قيم كل طبقة عشان تناسب منتجات المنشأة","إعداد برامج تسويقية تتلاءم مع رغبات وأذواق كل طبقة وتتفق مع المراكز الاجتماعية لأعضائها","توحيد برنامج تسويقي واحد يناسب كل الطبقات","معرفة الطبقة اللي يشوف كل فرد نفسه منها"],"answer":1,"why":"ش9: الدراسة تفيد في تفهم السوق وتقدير إمكانياته، ومعرفة القيم والميول والحاجات والاهتمامات والهوايات والأذواق لكل طبقة على حدة، «مما يساعد منشآت الأعمال في إعداد البرامج التسويقية التي تتلاءم مع رغبات وأذواق كل منها وتتفق مع المراكز الاجتماعية لأعضائها».","wrong":[{"i":0,"mis":"gen.reversed","note":"الهدف نتلاءم مع رغبات الطبقة، مو نغير قيمها."},{"i":2,"mis":"k6.one-mix-for-all","note":"الشريحة تقول «كل منها»، يعني برنامج يناسب كل طبقة لحالها."},{"i":3,"mis":"k6.personal-vs-others","note":"هذا وصف طرق الحكم الشخصي (ش11)، مو فايدة دراسة الطبقات."}],"tests":["فايدة دراسة خصائص الطبقات وحجمها","اللي نعرفه عن كل طبقة (6)"]},{"n":606,"lo":"CH6","sec":"MKT231-CH6","type":"list","topic":"مجموعات طرق القياس","stem":"تنقسم طرق قياس الطبقة الاجتماعية إلى ثلاث مجموعات رئيسية. وش هي؟","options":["الحكم الشخصي، الحكم على الآخرين، القياس الموضوعي","المتغير الواحد، المتغيرات المتعددة، القياس الموضوعي","وارنر، هولنجزهد، كولمان","الوظيفة، التعليم، الدخل"],"answer":0,"why":"ش10: «تنقسم طرق قياس الطبقة الاجتماعية إلى ثلاث مجموعات رئيسية»: طرق الحكم الشخصي، طرق الحكم على الآخرين، طرق القياس الموضوعي. المتغير الواحد والمتعددة نوعين جوا القياس الموضوعي (ش14).","wrong":[{"i":1,"mis":"k6.single-vs-multi","note":"المتغير الواحد والمتعددة أقسام القياس الموضوعي نفسه، مو مجموعات موازية له."},{"i":2,"mis":"gen.partial","note":"هذي من مؤشرات المتغيرات المتعددة (4، ش17)، وناقصها الحكومة الأمريكية."},{"i":3,"mis":"gen.neighbor","note":"هذي متغيرات تستخدم في طرق المتغير الواحد (ش14–16)، مو مجموعات طرق."}],"tests":["مجموعات طرق القياس (3)"]},{"n":607,"lo":"CH6","sec":"MKT231-CH6","type":"scenario","topic":"طرق الحكم الشخصي","stem":"فندق في أبها وزع على نزلائه استبانة بسيطة فيها سؤال واحد: «من أي طبقة اجتماعية تعتبر نفسك؟». وش الطريقة المستخدمة، ووش أكبر عيب فيها؟","options":["القياس الموضوعي لأنه استخدم استبانة، وعيبها صعوبة جمع البيانات","الحكم على الآخرين، وعيبها تحتاج مجتمع صغير مغلق","الحكم الشخصي، وعيبها صعوبة الاستخدام وتعقيده","الحكم الشخصي، وعيبها التصنيف يطلع غير مطابق للواقع ويعاني من التحيز"],"answer":3,"why":"ش11: الحكم الشخصي = استبانة بسيطة والفرد يحدد بنفسه الطبقة اللي يعتقد ينتمي لها. مزاياها البساطة وسهولة الاستخدام، وعيبها «غير مطابق للواقع ويعاني من التحيز».","wrong":[{"i":0,"mis":"k6.questionnaire-trap","note":"الاستبانة موجودة في الحكم الشخصي كمان. هنا النزيل صنف نفسه، فهي حكم شخصي."},{"i":1,"mis":"k6.personal-vs-others","note":"الحكم على الآخرين = مجموعة منتقاة تصنف الناس، مو الشخص يصنف نفسه."},{"i":2,"mis":"gen.reversed","note":"الطريقة تتصف «بالبساطة وسهولة الاستخدام»، فقلبت الميزة لعيب."}],"tests":["طرق الحكم الشخصي","مزايا وعيوب الحكم الشخصي"]},{"n":608,"lo":"CH6","sec":"MKT231-CH6","type":"scenario","topic":"طرق الحكم على الآخرين","stem":"باحث يدرس قرية تراثية صغيرة في عسير، وطلب من خمسة من كبار القرية يثق في خبرتهم يصنفون الأهالي لطبقات اجتماعية. وش الطريقة، ووش اللي لازم يتوفر عشان تنجح؟","options":["الحكم على الآخرين، وتحتاج مجتمع كبير مفتوح عشان العينة تكون أوسع","الحكم على الآخرين، وتحتاج مجتمع صغير مغلق يعرف فيه المصنفين باقي الأفراد معرفة جيدة","الحكم الشخصي، لأن الكبار يستخدمون حكمهم الشخصي","القياس الموضوعي، لأن المصنفين خبراء"],"answer":1,"why":"ش12: إسناد مهمة التصنيف إلى مجموعة منتقاة يثق الباحث في خبرتهم = الحكم على الآخرين. ومن مشاكلها: المصنفين «مايزالون يستخدمون حكمهم الشخصي»، و«تتطلب مجتمعاً صغيراً مغلقاً» يعرفون فيه الكل.","wrong":[{"i":0,"mis":"gen.reversed","note":"الشريحة تقول مجتمع صغير مغلق، مو كبير مفتوح."},{"i":2,"mis":"k6.personal-vs-others","note":"صح المصنفين لسا فيهم حكم شخصي، بس الطريقة اسمها الحكم على الآخرين لأن غيرك يصنفك."},{"i":3,"mis":"gen.neighbor","note":"خبرة الأشخاص ما تخليها موضوعية. الموضوعي يعتمد على متغيرات زي الوظيفة والدخل (ش13)."}],"tests":["طرق الحكم على الآخرين","مشاكل ومحددات الحكم على الآخرين (2)"]},{"n":609,"lo":"CH6","sec":"MKT231-CH6","type":"scenario","topic":"طرق القياس الموضوعي","stem":"شركة سياحة جمعت باستبانات وظيفة كل عميل ومقدار دخله وحجم ثروته ومستوى تعليمه، وأضافت الرمز البريدي لمنطقته السكنية عشان تعرف الأحياء اللي فيها تجمعات كبيرة من طبقة معينة. وش مجموعة الطرق المستخدمة؟","options":["طرق الحكم الشخصي","طرق الحكم على الآخرين","طرق القياس الموضوعي","مؤشر المركز الاجتماعي الحضري لكولمان"],"answer":2,"why":"ش13: القياس الموضوعي يعتمد على معايير موضوعية (وظيفة، دخل، ثروة، تعليم) تنجمع بالاستبانات، والباحث ممكن يضيف المنطقة السكنية ورمزها البريدي عشان يحدد المناطق اللي فيها تجمعات كبيرة لطبقات معينة.","wrong":[{"i":0,"mis":"k6.questionnaire-trap","note":"الاستبانة هنا تجمع متغيرات موضوعية، والعميل ما صنف نفسه."},{"i":1,"mis":"k6.personal-vs-others","note":"ما فيه مجموعة منتقاة تصنف الناس هنا."},{"i":3,"mis":"gen.neighbor","note":"كولمان له 6 متغيرات محددة فيها وظيفة الزوجين والمؤسسة الدينية والاجتماعية، وهذي ما انذكرت."}],"tests":["طرق القياس الموضوعي","أمثلة متغيرات القياس الموضوعي (4)","المعلومات الجغرافية المضافة (2)"]},{"n":610,"lo":"CH6","sec":"MKT231-CH6","type":"tf","topic":"المرحلة الثانية: تحديد الطبقات المستهدفة","stem":"صح أو خطأ: «في مرحلة تحديد الطبقات الاجتماعية المستهدفة، تختار المنشأة الطبقة اللي تقدر تخدمها بصورة أفضل وتحقق أهدافها في نفس الوقت، بعد ما تراجع مواردها المالية والمادية والبشرية وتقارنها باحتياجات كل طبقة».","options":["صح","خطأ"],"answer":0,"why":"ش24: هذي بالضبط المرحلة الثانية: تصنيف وتوصيف، تقدير حجم كل طبقة وقوتها الشرائية، بعدين اختيار الطبقة بمراجعة الموارد المالية والمادية والبشرية ومقارنتها بمتطلبات واحتياجات كل طبقة على حدة.","wrong":[{"i":1,"mis":"k6.strategy-stage-order","note":"مراجعة الموارد والاختيار جوا المرحلة الثانية فعلاً، مو الأولى ولا الثالثة."}],"tests":["المرحلة الثانية: تحديد الطبقات المستهدفة","موارد المنشأة (3)"]},{"n":611,"lo":"CH6","sec":"MKT231-CH6","type":"term","topic":"الوظيفة كمؤشر","stem":"أي متغير وصفته ش15 بأنه «من أفضل المتغيرات تعبيراً عن الطبقة الاجتماعية للفرد» لأنه يعكس المركز الاجتماعي لصاحبه؟","options":["المستوى التعليمي","الدخل الشهري أو السنوي","جودة المنطقة السكنية","الوظيفة (Occupation)"],"answer":3,"why":"ش15: «تعتبر الوظيفة (Occupation) من أفضل المتغيرات تعبيراً عن الطبقة الاجتماعية للفرد لأنها تعكس المركز الاجتماعي لصاحبها». التعليم وصفته «أحد المؤشرات المعبرة» بس.","wrong":[{"i":0,"mis":"gen.keyword","note":"التعليم «أحد المؤشرات المعبرة»، مو «من أفضل المتغيرات»."},{"i":1,"mis":"gen.neighbor","note":"الدخل تستخدمه «طائفة من مديري التسويق» (ش16)، والشريحة ما قالت عنه أفضل."},{"i":2,"mis":"k6.secondary-vars-alone","note":"جودة المنطقة نادراً تستخدم وحدها، دورها إضافي للتأكد (ش16)."}],"tests":["الوظيفة كمؤشر","Occupation"]},{"n":612,"lo":"CH6","sec":"MKT231-CH6","type":"tf","topic":"المستوى التعليمي كمؤشر","stem":"صح أو خطأ: «حسب ش15، فيه ارتباط طردي بين التعليم والوظيفة والدخل في أغلب الأحوال، فكلما ارتفع المستوى التعليمي ارتفع دخل الفرد وشغل وظيفة أعلى».","options":["صح","خطأ"],"answer":0,"why":"ش15 بالنص: «كلما ارتفع المستوى التعليمي ارتفع دخل الفرد وشغل وظيفة أعلى ... هناك ارتباط طردي بين كل من التعليم والوظيفة والدخل في أغلب الأحوال».","wrong":[{"i":1,"mis":"gen.reversed","note":"الارتباط طردي مو عكسي، والجملة منقولة من الشريحة تقريباً بالحرف."}],"tests":["المستوى التعليمي كمؤشر","الارتباط الطردي (3)"]},{"n":613,"lo":"CH6","sec":"MKT231-CH6","type":"concept","topic":"الدخل كمؤشر","stem":"حسب ش16، فيه طريقتين لاستخدام الدخل في تقدير الطبقة الاجتماعية. وش هي؟","options":["الدخل الشهري والدخل السنوي","دخل الفرد ودخل الأسرة","مقدار الدخل ومصدر الدخل","الدخل والثروة"],"answer":2,"why":"ش16: «وهناك طريقتان لاستخدام الدخل في تقدير الطبقة الاجتماعية تعتمد إحداهما على مقدار الدخل وتعتمد الأخرى على مصدره». الشهري أو السنوي، وللفرد أو للأسرة، هذي أشكال الدخل اللي يستخدمونها مو الطريقتين.","wrong":[{"i":0,"mis":"gen.detail","note":"شهري أو سنوي مذكور في نفس الشريحة، بس مو هو «الطريقتين»."},{"i":1,"mis":"gen.detail","note":"للفرد أو للأسرة مذكور كمان، بس الطريقتين مقدار ومصدر."},{"i":3,"mis":"gen.neighbor","note":"الثروة متغير ثاني (ش13)، مو طريقة لاستخدام الدخل."}],"tests":["الدخل كمؤشر","طرق استخدام الدخل (2)"]},{"n":614,"lo":"CH6","sec":"MKT231-CH6","type":"tf","topic":"المتغيرات الأخرى كمعيار","stem":"صح أو خطأ: «جودة المنطقة السكنية والقيمة المالية للمسكن المملوك وقيمة الممتلكات الشخصية تستخدم غالباً لحالها للحكم على الطبقة الاجتماعية».","options":["صح","خطأ"],"answer":1,"why":"ش16: هذي المتغيرات ممكن تستخدم منفردة، «ولكن نادراً ما تستخدم هذه المتغيرات وحدها»، وتستخدم «كوسيلة إضافية للتأكد من صحة التصنيف» اللي طلع من مؤشر ثاني زي المركز الوظيفي أو الدخل.","wrong":[{"i":0,"mis":"k6.secondary-vars-alone","note":"«غالباً لحالها» عكس «نادراً ما تستخدم وحدها»."}],"tests":["المتغيرات الأخرى كمعيار (3)"]},{"n":615,"lo":"CH6","sec":"MKT231-CH6","type":"concept","topic":"المتغير الواحد مقابل المتغيرات المتعددة","stem":"طرق القياس الموضوعي نوعين: ذات المتغير الواحد وذات المتغيرات المتعددة. أي واحد من هذي من طرق القياس ذات المتغيرات المتعددة؟","options":["الوظيفة كمؤشر للطبقة الاجتماعية","مؤشر الطبقة الاجتماعية لهولنجزهد","الدخل كمؤشر للطبقة الاجتماعية","طرق الحكم على الآخرين"],"answer":1,"why":"ش14 تقسم القياس الموضوعي لنوعين، وش17 تذكر 4 طرق للمتغيرات المتعددة: وارنر، هولنجزهد، الحكومة الأمريكية، كولمان. الوظيفة والدخل كل واحد لحاله = متغير واحد.","wrong":[{"i":0,"mis":"k6.single-vs-multi","note":"الوظيفة لحالها متغير واحد (ش14–15)."},{"i":2,"mis":"k6.single-vs-multi","note":"الدخل لحاله متغير واحد (ش16)."},{"i":3,"mis":"gen.neighbor","note":"الحكم على الآخرين مجموعة مستقلة (ش12)، مو من القياس الموضوعي أصلاً."}],"tests":["أنواع القياس الموضوعي (2)","طرق القياس ذات المتغير الواحد","طرق المتغيرات المتعددة (4)"]},{"n":616,"lo":"CH6","sec":"MKT231-CH6","type":"figure","topic":"مؤشر وارنر","stem":"في مؤشر وارنر لخصائص المركز الاجتماعي (ش18)، وش المتغيرات وأوزانها الصحيحة؟","img":"img/mkt231/CH6-s18.png","options":["الوظيفة 9، نوع المسكن 6، مستوى التعليم 5","الوظيفة 4، مقدار الدخل 3، نوع المسكن 2، جودة المنطقة السكنية 1","الوظيفة 4، مصدر الدخل 3، نوع المسكن 2، جودة المنطقة السكنية 1","جودة المنطقة السكنية 4، نوع المسكن 3، مصدر الدخل 2، الوظيفة 1"],"answer":2,"why":"ش18: وارنر (1941) أربعة متغيرات مرجحة بالأوزان: الوظيفة (4 وحدات)، مصدر الدخل (3)، نوع المسكن (وحدتان)، جودة المنطقة السكنية (وحدة واحدة)، ويصنف الناس لست طبقات. والشريحة تنبه: «يستخدم مصدر الدخل وليس مقداره».","wrong":[{"i":0,"mis":"k6.index-numbers-mixup","note":"هذي أوزان هولنجزهد (ش19)."},{"i":1,"mis":"k6.warner-income-amount","note":"وارنر يستخدم مصدر الدخل مو مقداره."},{"i":3,"mis":"gen.reversed","note":"قلبت الترتيب: الوظيفة أعلى وزن (4) وجودة المنطقة أقل وزن (1)."}],"tests":["مؤشر وارنر","متغيرات وارنر وأوزانها (4)","مصدر الدخل مو مقداره"]},{"n":617,"lo":"CH6","sec":"MKT231-CH6","type":"figure","topic":"مؤشر هولنجزهد","stem":"وش الصحيح عن مؤشر الطبقة الاجتماعية لهولنجزهد (ش19)؟","img":"img/mkt231/CH6-s19.png","options":["بدأ استخدامه 1958، ثلاث متغيرات (المسكن 6، الوظيفة 9، التعليم 5)، ويقسم المجتمع خمس طبقات","انعد 1941، أربع متغيرات، ويقسم المجتمع ست طبقات","بدأ استخدامه 1958، ثلاث متغيرات، ويقسم المجتمع ست طبقات","بدأ استخدامه 1958، وفيه مصدر الدخل بوزن 3 وحدات"],"answer":0,"why":"ش19: «بدأ استخدام هذا المؤشر في عام ١٩٥٨م»، على ثلاث متغيرات: نوع المسكن (6 وحدات) والوظيفة (9) ومستوى التعليم (5)، و«يقسم أفراد المجتمع إلى خمس طبقات اجتماعية وليس ستاً». وما فيه دخل أصلاً.","wrong":[{"i":1,"mis":"k6.index-numbers-mixup","note":"هذا وصف وارنر (ش18)."},{"i":2,"mis":"k6.index-numbers-mixup","note":"الست طبقات لوارنر، هولنجزهد خمس «وليس ستاً»."},{"i":3,"mis":"k6.index-numbers-mixup","note":"مصدر الدخل بوزن 3 في وارنر، وهولنجزهد ما فيه دخل."}],"tests":["مؤشر هولنجزهد","متغيرات هولنجزهد وأوزانها (3)","عدد الطبقات في وارنر وهولنجزهد"]},{"n":618,"lo":"CH6","sec":"MKT231-CH6","type":"scenario","topic":"مقياس الحكومة الأمريكية","stem":"مدير تسويق في شركة رحلات يبي مؤشر متعدد المتغيرات، متغيراته سهلة القياس وبطريقة موضوعية، ومقبول ومستخدم كثير بين مديري التسويق، ويحسب دخل الأسرة كله بما فيه دخل الزوجة والأولاد لو يشتغلون. أي مؤشر يناسبه؟","options":["مؤشر وارنر لخصائص المركز الاجتماعي","مؤشر المركز الاجتماعي الحضري لكولمان","مقياس الحكومة الأمريكية للمركز الاجتماعي – الاقتصادي","مؤشر الطبقة الاجتماعية لهولنجزهد"],"answer":2,"why":"ش20: مقياس الحكومة الأمريكية = 3 متغيرات مرجحة: الوظيفة، ودخل الأسرة (بما فيه دخل الزوجة والأولاد لو يشتغلون)، والمستوى التعليمي. ولسهولة قياسها كلها وبطريقة موضوعية هو «من أكثر المؤشرات قبولاً واستخداماً بين مديري التسويق».","wrong":[{"i":0,"mis":"k6.warner-income-amount","note":"وارنر يستخدم مصدر الدخل، مو دخل الأسرة كله."},{"i":1,"mis":"k6.usgov-vs-coleman","note":"كولمان فيه وظيفة الزوجة بس ما فيه دخل، وهو لسكان المدينة، والشريحة ما قالت عنه الأكثر استخداماً."},{"i":3,"mis":"gen.neighbor","note":"هولنجزهد ما فيه دخل أصلاً (مسكن ووظيفة وتعليم)."}],"tests":["مقياس الحكومة الأمريكية","متغيرات الحكومة الأمريكية (3)","الأكثر قبولاً واستخداماً"]},{"n":619,"lo":"CH6","sec":"MKT231-CH6","type":"concept","topic":"مؤشر كولمان","stem":"أي مؤشر صمم أساساً لتقدير المراكز الاجتماعية لسكان المدينة، ومن متغيراته المؤسسة الدينية اللي تنتمي لها الأسرة والمؤسسات الاجتماعية المحلية؟","options":["مؤشر المركز الاجتماعي الحضري لكولمان","مقياس الحكومة الأمريكية","مؤشر وارنر","مؤشر هولنجزهد"],"answer":0,"why":"ش21: كولمان «صمم هذا المقياس أساساً بهدف تقدير المراكز الاجتماعية لسكان المدينة»، و6 متغيرات: وظيفة الزوج والزوجة، تعليم كل منهما، جودة المنطقة السكنية، نوع المسكن، المؤسسة الدينية (الكنيسة)، والمؤسسات الاجتماعية المحلية.","wrong":[{"i":1,"mis":"k6.usgov-vs-coleman","note":"الحكومة الأمريكية 3 متغيرات بس: الوظيفة ودخل الأسرة والتعليم."},{"i":2,"mis":"k6.index-numbers-mixup","note":"وارنر 4 متغيرات ما فيها مؤسسات."},{"i":3,"mis":"k6.index-numbers-mixup","note":"هولنجزهد 3 متغيرات: المسكن والوظيفة والتعليم."}],"tests":["مؤشر كولمان","متغيرات كولمان (6)"]},{"n":620,"lo":"CH6","sec":"MKT231-CH6","type":"list","topic":"شروط المقياس المناسب","stem":"أي واحد من هذي مو من شروط المقياس المناسب في ش22؟","options":["يساعد في تحديد الطبقات الاجتماعية الحقيقية للأفراد","يكفي يميز بين الحالات المتطرفة على السلم الاجتماعي","يرتب الأفراد بنفس الطريقة لو أعيد استخدامه على عينة ثانية مماثلة من نفس المجتمع","يعطي نتائج دقيقة بصرف النظر عن التغيرات الاجتماعية والاقتصادية"],"answer":1,"why":"ش22: الشرط يقول المقياس لازم يميز «بين الحالات القريبة جداً من بعضها على السلم الاجتماعي وليس فقط بين الحالات المتطرفة». الشروط الستة: الحقيقية، العينة المناسبة، المتغيرات الموضوعية، التمييز بين القريبين، نفس الترتيب لو تكرر، الدقة رغم التغيرات.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا الشرط الأول بالنص."},{"i":2,"mis":"gen.detail","note":"هذا الشرط الخامس."},{"i":3,"mis":"gen.detail","note":"هذا الشرط السادس."}],"tests":["شروط المقياس المناسب (6)"]},{"n":621,"lo":"CH6","sec":"MKT231-CH6","type":"list","topic":"مراحل الإستراتيجية التسويقية","stem":"وش الصحيح عن مراحل إعداد الإستراتيجية التسويقية للطبقات الاجتماعية المختلفة (ش23–26)؟","options":["3 مراحل تبدأ بتصميم الموقع التنافسي للمنتج","4 مراحل تبدأ باختيار الطبقة المستهدفة قبل أي دراسة للاستهلاك","4 مراحل تنتهي بمزيج تسويقي واحد موحد لكل الطبقات","4 مراحل: تحديد العلاقة، تحديد الطبقات المستهدفة، تصميم الموقع التنافسي، وأخيراً خطة تسويقية (منتجات، تسعير، ترويج، توزيع) بمزيج خاص لكل طبقة"],"answer":3,"why":"ش23: «تمر بأربع مراحل»: أولاً تحديد العلاقة بين المكانة الاجتماعية للفرد واستهلاكه للمنتج، ثانياً تحديد الطبقات المستهدفة، ثالثاً تصميم الموقع التنافسي المناسب للمنتج، رابعاً إعداد الخطة التسويقية. وش26 تقول المزيج 4 عناصر و«يعد مزيج تسويقي خاص لكل طبقة اجتماعية على حدة».","wrong":[{"i":0,"mis":"k6.strategy-stage-order","note":"المراحل 4، وتصميم الموقع التنافسي هو الثالث مو الأول."},{"i":1,"mis":"k6.strategy-stage-order","note":"الاستهداف ثاني، وقبله لازم دراسة العلاقة بين المكانة والاستهلاك."},{"i":2,"mis":"k6.one-mix-for-all","note":"الشريحة تطلب مزيج خاص لكل طبقة على حدة."}],"tests":["مراحل الإستراتيجية التسويقية (4)","المرحلة الثالثة: تصميم الموقع التنافسي","المرحلة الرابعة: الخطة التسويقية","عناصر المزيج التسويقي (4)"]},{"n":622,"lo":"CH6","sec":"MKT231-CH6","type":"scenario","topic":"المرحلة الأولى: تحديد العلاقة","stem":"شركة طيران سوت دراسة تقيس طبقات المسافرين وأساليبهم المعيشية الحالية والمرغوبة، وربطتها بتوقيت سفرهم ومعدله، ودوافعهم، والمكان اللي يحجزون منه، ووسائل الإعلام اللي يتابعونها، ومعنى درجة الأعمال كرمز عندهم. هذي أي مرحلة من مراحل الإستراتيجية؟","options":["المرحلة الأولى: تحديد العلاقة بين المكانة الاجتماعية للفرد واستهلاكه للمنتج","المرحلة الثانية: تحديد الطبقات الاجتماعية المستهدفة","المرحلة الثالثة: تصميم الموقع التنافسي المناسب للمنتج","المرحلة الرابعة: إعداد الخطة التسويقية"],"answer":0,"why":"ش23: المرحلة الأولى تحتاج دراسة تقيس الطبقات وأساليب المعيشة الحالية والمرغوبة، بعدين تربط الطبقة بالأنماط الاستهلاكية: كيفية الاستعمال وتوقيته ومعدله، ودوافع الشراء وأسبابه، ونوع المحل، ووسائل الإعلام، والمعاني الرمزية للمنتج.","wrong":[{"i":1,"mis":"k6.strategy-stage-order","note":"الثانية فيها التصنيف وتقدير الحجم والقوة الشرائية واختيار الطبقة، مو دراسة الأنماط."},{"i":2,"mis":"k6.strategy-stage-order","note":"الثالثة تصميم موقع تنافسي بعد ما نختار الطبقة."},{"i":3,"mis":"k6.strategy-stage-order","note":"الرابعة المزيج التسويقي، وهي آخر خطوة."}],"tests":["المرحلة الأولى: تحديد العلاقة","الأنماط الاستهلاكية (5)","العادات الاستهلاكية المتعلقة بالاستعمال (3)"]}]};
